/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20190304-3","meetingId":"r01-c-budget","date":"2019年3月4日","dateIso":"2019-03-04","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を165件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）副委員長","kind":"質問・要望","question":"会派におかれましては、１人当たりの質問時間は答弁時間も含めて１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"３５ページです。今回補正で上がっているのは現年度分ということですけれど、最初、予算書では収入率も示された上で予算額を立てられていると思いますが、収入率はどのような感じでしょうか。そして滞納分が毎年あって、それが３５％ほどで収入見込みを立てていたと思いますが、そのあたりはどうなっているのか教えてください。入ってこなくなった場合、どういう扱いになるのか教えてください。","respondent":"伊東税務課長","answer":"そのような現状から見まして、増の見込みを立てたところです。それと収入率の関係につきましては、当初高く見ているところはありますけれども、これも現状では例年並み、昨年並みの収入率は確保できるということで、このような形での増収見込みが立てられるです。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"ありがとうございました。区民税の伸びは承知しておりまして、これから先、品川区の人口も増えてくるということでございましょうし、一般的には景気がよくなって、納税する方も増えて、ということですから、これから特別徴収も増えていくのかなという中で、ただ企業の状態等によってはこういうことがまた今後あるかもしれないということで、確認させていただきました。カード決済はどういう状況でしょうか。","respondent":"伊東税務課長","answer":"クレジットカードでの納付の関係です。昨年１月からクレジットカードでの納付を始めたところですが、平成３０年度で申しますと件数で５,２１６件、金額にしますと４億３,０００万円納付いただいているところです。","id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"私もこれは研究して、次にどこかで質問しようと思います。ありがとうございました。そういう中で、例えば区民の方々に、基金というのはどういうものであって、どういう性質で、どのように使っていくべきものかというのを、やはり周知していったほうがいいのかなと思うのです。その辺の基金に対する考え方、周知に対する考え方をお聞かせいただきたいのですけれど、よろしいでしょうか。","respondent":"品川財政課長","answer":"これから長期基本計画を策定していく中で、財政計画のほうも作成していく予定です。こういった中で、基金のあり方、今後の使い方等も示していくようなことを検討していきたいと考えています。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"これから先の需要が見えているわけですから、大まかにお示しいただくのも、それが一番いいのかもしれませんが、示せるのであればある程度、具体的に細かい話でなくても、こういう施設が必要です、学校は１年に１校ずつやっていきますというふうに言えば、幾らぐらいまでは出せるという話ができると思うので、少し細かく出していただくことによって、基金がこれぐらい必要で。","respondent":"品川財政課長","answer":"先ほど委員からお話がありました具体的な数字というところも、なかなかお示しするのも難しいのですが、ただ極力そういった考え方でやっていきたいと考えています。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"もう１点は、３０代、４０代の利用実績についてお伺いしたいと考えています。私のところにご相談に来られる方を見ていると、高齢の方、少し年代が上のひきこもりの方が多いと私は認識しておりまして、こういう方の実績があるのか、またこういう方がどのように子ども若者応援フリースペースにつながってきているのか、お伺いしたいと思います。","respondent":"高山子ども育成課長","answer":"２点目の利用者の声という点で申しますと、以前は午前と午後の開設だったのが、夕方の時間帯も順次開設時間を延長してきたこともございまして、学校帰りの子どもたち、かつての利用者がまた再び戻ってくる場所という形で、塾の帰り。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"ありがとうございました。この存在が周知不足ではないかというご指摘がありました。このことに関して、対策また改善をしてほしいと思いますが、いかがでしょうか。そしてまた、現在ゆうゆうプラザでは週１回、そして拡充されてから中延二丁目の場所では月、水、金の週３回ということですが、１日平均二、三十人の利用があるということで、開催日を更に増やしていくお考えがあるのかどうか、お伺いいたします。","respondent":"高山子ども育成課長","answer":"昨年の７月オープンから、私どもとしましてはいろいろな、例えば民生委員の協議会の場でありますとか、あるいは地元町会など、主に荏原地域などを中心とした説明なども行ってくるとともに、もちろん区のホームページでありますとか。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"高齢化率も約４％ということで聞いておりますけれども、この勝島地域におきまして、今後の需要をどう捉えているのか、この地域への拡大のお考えをお伺いしたいと思います。そしてもう１点は、窓口の相談対応についてであります。そういう中で、二次への相談体制は既に今もされていることと思うのですが、より一層、寄り添った具体的なアドバイスを求めたいと思いますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"３点目の二次の発表までの窓口の対応ですが、２月８日に発表いたしまして、２月２０日の二次の締め切りまで、短い期間で入園相談係１３名で対応しています。従前から認証、認可外等の案内をしていますが、隣の保育支援課と連携をとって、丁寧な対応に努めていきたいと思います。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。続いて児童センターの運営費についてお伺いいたします。この建物についてお伺いするのですが、これは区有施設でありますので、建物の建て替えや修繕におきましては、計画にのっとって進められていることと認識しております。この児童センターの設計とかデザインにおいては、どのような流れになっているのか、区としてそういうことが要望していけるのか、お伺いしたいと思います。","respondent":"高山子ども育成課長","answer":"一般的には、区の施設ですので、施設整備の部門で入札などかけまして、選定業者を決めていくわけなので、基本的な成り立ちとしては他の区有施設と同様ということになってくるのですが、基本設計、実施設計の段階で現場で働いている職員の意見などを踏まえて。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。いかにも区有施設という施設ではなくて、子どもたちが喜んで集ってこれる、そういうデザインにも特化した児童センターの設計を、ぜひ目指していただきたいと思いますことを要望して、終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"８ページの歳入補正全般と、６９ページの武蔵小山駅周辺地区再開発について、お伺いいたします。この３款だけで当初予算よりも１１９億円余の大幅増になっています。どうしてなのか、伺います。基金からの取り崩しも７５億５,０００万円余、取り崩さずに済んでしまうといったことでは、さらに残して基金１,０００億円に積み増していくのではなく、区民要求に応えるべきと思っていますが、いかがでしょうか。","respondent":"品川財政課長","answer":"こういった状況の中で、今回歳入が増えているです。それに対して今回の補正予算については、この上がった部分について基金に回していこうという流れで、組んです。必要なところにきちんと予算は当てるという形で、今回も補正予算を出しております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"第２３回品川区世論調査が１月に出されました。分厚い資料が出ました。１０年以上が４２.９％、うち３０年以上は１４％しかいないといったことでは、住み続けたくても住み続けられない人がいるのだなということが、明らかになったのではないでしょうか。共産党はこの間、２３区最低の福祉の改善を求めてきました。直ちに必要な福祉施設をつくるべきであると思いますが、いかがでしょうか。","respondent":"柏原企画調整課長、吉田保育施設調整担当課長","answer":"我々もさまざまニーズ、施策を進める上で、必要な施設、必要な施策を進めていくといったところです。例えば施設をつくるに当たっても、土地であるとかその地域のニーズ、お声であるとか、さまざまなことを考えながら進めていくものです。子ども・子育て支援事業計画というものがございまして、これは今、平成３２年度からの新しい事業計画の策定を進めております。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特養と老人保健施設の整備はたびたび申し上げていますけれども、あわせて２３区最低の整備率です。ここをもう一度答えていただきたいと思います。住宅建て替えや不燃化への支援事業を区内全域で実施すること、公的支援を強めていくことこそ必要であると思っていますが、いかがでしょうか。そういった意味でマンションの耐震補強の支援を強化すべきであると思いますが、いかがでしょうか。","respondent":"大串福祉計画課長、長尾建築課長","answer":"今後ともそういった高齢者の状態像の変化に応じた形、ニーズの変化に応じた多様な整備を、行っていきたいと考えているところです。品川区としましては、木造住宅の耐震化につきましては、耐震診断、補強設計、改修工事、除却といった、全ての支援内容を更新しながら、改修工事につきましては既に区内全域で対応しています。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"計画を出さないで、どうやって努力している、やりますと言って実現するのでしょうか。ぜひ計画を立てる、当たり前のことを実際にやっていただきたいと思います。広く公表して、この教訓を生かしていくことが大事であると思っていますが、区民の命を守るために、同様の事故防止のために、今回の事故を公表し、二度と起こらないような教訓を皆で学ぶべきであると思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"パルム駅前地区の荷揚げ用かごの床材、板が落下したということが、昨年１２月２８日に起こりました。委員おっしゃるとおり、近隣のマンションのベランダに落ちたということで、人的被害はないということでした。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当に重大な事故だと思います。事業者だけでなく、区民にもぜひ知らせてください。何があったか、ほとんどの方が知らない、私は毎日通っています。風に飛ばされて道路上に飛んできたら、どういうことになるか。それぞれのところでどう考えているのか、返事もちゃんといただきたいと思います。都や品川区に対して、被害者の方は要望書も出しています。ぜひ答えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"私からは５１ページの補助２６号線開通記念事業の１,４９３万５,０００円減について、６３ページのチャレンジマート事業助成１,０６０万円減について、同じく６３ページの大井町駅周辺バリアフリー工事費の１億２,０００万円減について、最後に６７ページの不燃化１０年プロジェクトの５億１,９８６万円減について、伺います。初めに、５１ページの補助２６号線開通記念事業について伺います。","respondent":"鈴木都市計画課長","answer":"補助２６号線の整備の進捗ですが、東京都第二建設事務所からは最終的な、タコ公園の前の擁壁工事、これは再三入札をかけていたのですが、なかなか業者が決まらなかったということで、ようやく業者も決まりました。そのせいで、工事のほうが遅れてきていたです。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"この補正予算の減額ですが、この１,４９３万５,０００円は主にどういったところに使われる予定だったのか、お知らせください。この補助２６号線開通記念事業に参加される予定である方々について、今回開通できなかったことについて、どのようにご説明されたのか、あわせて伺います。","respondent":"伊崎地域活動課長","answer":"参加する方々への直接の説明ということですが、補助２６号線開通記念事業の実行委員会というものを、地域の方を中心として進めてございまして、その中で委員長の采配のもとに、区の担当者から工事の遅れにより、開通が予定よりも遅れるということをご説明さしあげ。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"そうした理由で、開通できなかったということでありました。皆さんにはそういった形で説明をされているということでありましたが、来年度は開通するということでしたでしょうか。改めていつごろ開通するのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"入札の関係で、当初平成３０年度末というふうに東京都からは聞いていた開通予定でございましたが、今のところの日程は、平成３２年度末に開通予定ということで聞いているところです。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ東京都には早期に開通できるよう、要望していただきたいと思いますので、よろしくお願いいたします。次に、６３ページのチャレンジマート事業助成１,０６０万円減について、伺います。あわせて伺います。","respondent":"山崎商業・ものづくり課長","answer":"空き店舗対策ということで、北品川商店街のほうで平成２９年９月に商店街に空き店舗が生じ、そこを活用して例えば国際交流の拠点、他国籍交流スタンドというふうな計画がたてられまして、区としましては平成３０年度予算の編成ということに当たっていた時期でございましたので。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"そうした中でぜひ、これは対象条件が厳しいのではないか、また事業の条件を改正されることはお考えでしょうか。実績を上げることについてはそういった方法も考えられると思うのですが、本区の考えについてお知らせください。","respondent":"山崎商業・ものづくり課長","answer":"実は東京都も商店街の開業応援事業というものがあり、区の制度とそうした東京都の制度のいいところをとりまして、大切なのは空き店舗を解消して活力を生むですので、さまざま工夫して取り組んでまいりたいと考えているところです。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"ぜひよろしくお願いします。次に、同じ６３ページの大井町駅周辺バリアフリー工事についてです。ここも１億２,０００万円の減額なのですが、このバリアフリー工事の内容についてお知らせください。恐らく工期が遅れていると思うのですが、なぜ工期が遅れてしまっているのか、大井町駅周辺と書いてありますが、その場所について、あわせて伺います。","respondent":"多並道路課長","answer":"大井町駅周辺バリアフリー工事につきましては、平成２７年度から計画的に工事を進めているところです。今年度の予定としましては、ゼームス坂通りの約２７０メートルの工事を実施しようということで、予算化させていただきました。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"その２分割というのは、場所によって２分割なのか、どこで区切るのか、その辺について伺いたいと思います。","respondent":"多並道路課長","answer":"分割というのは、大井町駅の坂の上のほうから約半分、１４０メートルほどを平成３１年度予算に計上させていただき、残りの区間は平成３２年度に、坂の下のほうをやらせていただくということで、２工区に分けたです。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ早期によろしくお願いいたします。自転車レーン等も多分あると思いますが、ぜひよろしくお願いいたします。そうした面も含めて、ポールなり何かつけていただければと思うので、要望で終わります。最後に６７ページの不燃化１０年プロジェクト、５億１,９８６万円減について伺います。先ほどの説明では、実績見合いということでお聞きしましたが、その実績内容についてお知らせください。","respondent":"高梨木密整備推進課長","answer":"結果といたしましては、昨年度より２５％の伸びを示す予定なのですが、残念ながら当初予算額までは行かなかったというのが現状です。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"今後も不燃化事業は大きな地震がいつ来るかわからない、また火災も燃え広がらないようなまちづくりに努めていただきたいと思うのですが、最後に区として、今回実績があまりなかったということですが、来年度はどのような形で取り組んでいかれるのか、お伺いします。","respondent":"高梨木密整備推進課長","answer":"今年度、昨年度比約２５％増という形ですが、期限が終わった後に、この制度を知らなかったという方があらわれないよう、引き続きしっかりとまず周知に努めるということと、１人でも多くの方々に制度を利用していただくよう、丁寧な説明を尽くしていきたいと考えているところです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"３４ページの特別区民税と特別区交付金について、まずお伺いします。特別区交付金については、その原資の最も大きいものが固定資産税と、次に法人住民税だと思うのですけれども、それぞれの伸び率を教えてください。","respondent":"品川財政課長","answer":"固定資産税の伸び率としましては０.３％、法人住民税は１２.７％です。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"上がっているときはいいのですけれども、国が直接的にこの特別区から吸い上げていますよね、今の時点で。今は全体的に増収だからこれに対応していけると思うのですけれども、まずオリンピックが終わった後、確実ではないですけれども、他国の例を世界的に見ると必ず景気等は落ちていますよね。そういう意味において、オリンピック後をどういうふうに考えているか、今後の見通しと考え方を教えてください。","respondent":"品川財政課長","answer":"その１年後、当然企業の状況、固定資産税の状況等の変化に応じて、オリンピック後も変わってくるのではないかと考えております。要するに、オリンピックが終わって１年たって、その翌年ぐらいに少し変化が来るかもしれないというところで、考えております。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"課長、そういうことでいいのでしょうか。落ちたときはどうするのかということを、今から考えておかないと、本当に１年は早いですから、やはり財政としてはそこを考えておくべきだと思いますし、そういう意味において景気ですよね。","respondent":"品川財政課長","answer":"こういった総合的に景気の状況等、処々状況を見ながら、対応を考えていきたいと考えています。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"５％から８％に上がったとき、景気は落ちたではないですか。３００万円の方は食べるためにお金を使う。その辺を含めての危機感は、消費が落ちなければいい、オリンピック後も景気が落ちなければいい、それは望むところですけれども、やはりなったときにどうするのだということを、一番身近な区としては今からいろいろ考えておくべきだと思うのですけれども、その辺をよろしくお願いします。","respondent":"品川財政課長","answer":"ただ、そういう対応が行われているからといって、本当に景気のほうはどうなるかわかりませんので、そこは十分、視点を広げて注視しながら、今後の財政対策等含めて、施策を考えていきたいと考えています。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"注視して、施策等を実現していっていただきたいと思います。それと、５７ページの自立支援給付事務です。自立支援給付費が伸びているのですが、ある特定の会派からいつも出るのは、２３区で２３番目、つまり最低のレベルということをよく言われているのですけれども、これは実際にどういうふうに考えているのでしょうか。どうなのでしょうか。","respondent":"松山障害者福祉課長","answer":"自立支援給付のお尋ねです。こちらの増の要因ですけれども、平成３０年度の報酬改定と、実績というものは必要度に応じて給付しておりますので、その伸びです。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"ご答弁はよくわからなかったですが、誇りを持って、プライドを持ってください。２３区の中でも最低だとケーブルテレビ等で出ると、一般の区民の方は品川区は福祉に対して最低なのだと思われてしまうので、この点しっかりしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"４１ページ、１４款都支出金、２項都補助金、２目民生費補助金、児童保育費の認可外保育施設等保育料助成、６９ページ、６款土木費、４項都市計画費、３目都市開発費、武蔵小山駅周辺地区再開発事業について、伺います。認可外保育施設等保育料助成の減額理由は、事前に伺いました。認可外とベビーシッターの利用が想定より下回ったということですが、理由をどのように捉えているのか、お知らせください。","respondent":"大澤保育支援課長","answer":"認可外保育施設の保育料助成が下回った原因ですけれども、これは認可保育園の開設が平成３０年度１７園ということで、認可保育園で一定の需要に対して応えられたという成果だと認識しています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"認可外に対してはそうだったと思います。ベビーシッターは、たしか希望者がゼロだったということでしたけれども、そのベビーシッターについてです。園に預けるのではなく、子どもを見ていてほしいというニーズもあると思いますので、今の使いづらさの改善をこれから都に求めていくのか、それとも区で新しく制度をつくっていくのか、ベビーシッター助成の今後について、お知らせください。","respondent":"大澤保育支援課長","answer":"東京都のほうはベビーシッター助成について幅を広げて、額もかなり増やすということで、平成３１年度予算につきましては、区としましても拡大していくことを考えております。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"待機児童の数から外すなら、３歳児のときに保活しなくてもいい制度をつくるべきではないでしょうか。２００８年にできたこの制度は育休をもっととってもらおうという、保育課と保護者からの要望からできた制度だと聞いています。認可園との連携が不公平で困難ならば、ほかの方法でもいいので、ぜひ認証から保活の不安が払拭できるような制度を構築していただきたいと考えますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"使いづらさというのは、具体的にどういうことかというと、恐らくベビーシッターの額がやはり毎日使うとなるとかなり高くなりますので、そういう意味では現在、助成が５万円ですので、そういう意味では少し使い勝手はよろしくないかと認識しています。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"区外の認証に行かれた方、認証に入らざるを得なかった方たちのことを忘れてはいけないと思うのです。公平性というのはわかるのですけれども、待機児童に入らない、カウントされない認証に通わざるを得なかった子たちを、どうにかつなげる制度にしてほしいと思います。次に行きます。武蔵小山駅周辺地区再開発事業を聞きます。再開発事業費の減額理由と、減額による影響について、簡単にお知らせください。","respondent":"稲田都市開発課長","answer":"国費が今回配分額が減りましたために、それに連動して組合の補助金も減額したです。影響ですが、これは何年もかけてやる工事でございまして、全体の中で事業計画を見直しながらやっていきますので、大きな影響はないというふうに考えております。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"減額理由はわかりました。２０１８年の決算特別委員会で、武蔵小山駅周辺まちづくりビジョンでは、自転車の利用について推進する方向なのか、抑制する方向なのか伺ったところ、近い方は歩いてきてくださいという方針という答弁でした。自転車利用の状況から考え、商店街利用の方が快適に過ごせるように、駐輪場の設置場所の検討を区で進めるなど、何かしらの対策が必要だと考えますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"現在工事が行われておりますパルム駅前地区ですが、こちらには一般の方が利用できる駐輪場５００台を設置する予定でいます。それ以外に設置義務で、住宅用とか店舗用等があります。駅前通り地区にも店舗用等の駐輪場を設けていくと。","id":"exchange-035"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私のほうからは、５０ページ以降の人事管理費および職員手当等についてと、６４ページの河川下水道費の２点を伺わせていただきます。ちょっと私の調べ方の問題なのかもしれませんが、この「しながわ～く」の今までの方針であったりとか成果というのが、なかなかウェブ上で見つからなかったので、まずその成果を教えていただきたいのと、ウェブ上で公開されているのかも含めて伺わせてください。","respondent":"黒田人事課長、山本情報推進課長","answer":"「しながわ～く」に関するお尋ねですが、まず成果等についてはウェブ上に出ているかですが、まだ取り組みましたのが平成２９年度からでございまして、今年度、平成３０年度は基本方針を立てて取り組んでおりますが。権限範囲ですけれども、予定しているところでは、システム等のログインはできないという仕組みを考えているところです。","id":"exchange-036"},{"speaker":"芹澤委員","kind":"質問","question":"セキュリティ対策についてもう少しだけ伺いたいのですが、その端末というのは、もともと職員の方が自分で使っている端末とは別に、独立して端末を貸し出す予定なのかというのを、後ほどあわせて伺えればと思います。続けて、庁舎にいなくても仕事ができるというふうになりますと、夜間や休日でも業務が進められる一方で、勤務時間の管理というのがあやふやになるおそれがあります。","respondent":"山本情報推進課長","answer":"モバイルワークの時間の管理ですけれども、こちらの考え方としましては、就業時間内で外出先等でモバイルワークを行うという考え方です。それを持ち帰って仕事をするといったことは考えてございません。","id":"exchange-037"},{"speaker":"芹澤委員","kind":"確認","question":"続いて河川下水道費について伺います。河川下水道費は、結構補正予算でマイナスになっていると思います。この道路の管理についてであります。これは目黒川沿いだけではなくて、かむろ坂であったりとか、奥の歩道が既に盛り上がっているというのも確認しております。そのような声を解消するために、歩道の改修というのも順次進めていくべきかと思いますが、ご見解をお聞かせください。","respondent":"持田河川下水道課長","answer":"一遍に全部というのはなかなか難しいところではありますが、そういった事業も計画的に進めまして、桜を見ている方の安全ということに配慮して事業を進めているところです。","id":"exchange-038"},{"speaker":"芹澤委員","kind":"意見","question":"今ふるさと納税で桜並木にも注目が集まっているかと思いますので、その方々のためにもぜひ歩道の整備、桜を植えるだけではなくて、歩いて観賞できるような道路というのもぜひ力を入れて取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"債務負担行為の補正の変更のところなのですけれども、４点、オリンピック・パラリンピック施設周辺道路整備工事II工区、勝島歩道橋エレベーター等整備、しながわ区民公園南側ゾーン改修工事、しながわ区民公園水処理施設改修工事なのですけれども、これはやはり改めてこうして数字を並べてみますと、補正前と補正後の金額の乖離がかなり大きいなと思いまして。","respondent":"品川財政課長","answer":"債務負担行為の部分ですが、今回この４点につきましては、基本的には工事関係のものになります。４つの工事のそれぞれ調整等いろいろありまして、スケジュールが少しおくれる関係等もございまして、こういったことのところで工事費が減額補正という形でやっていくものです。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"これは減額になるのですか。債務負担が増えたということではないのですか。","respondent":"品川財政課長","answer":"失礼しました。それぞれ金額、すみません、私は全部減額と言ってしまったのですけれども、基本的には工事の延期、期間等の変更に伴いまして、それに伴う金額の調整をしているですので、ご理解いただければと思います。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"工期の延長をすることによって、工費もやはりそれなりに増えてきてしまうという理解でよろしいのでしょうか。","respondent":"品川財政課長","answer":"工期を基本的にずらすということになりますので、それに伴いまして、当初出していた金額といろいろ変動等がありますので、その部分につきまして、今回補正予算を上げているという状況です。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"やはり数字がかなり違いますので、例えば一番上９,５００万円のところが２億７,６００万円に補正されているということで、これはやはり工事の予測というのはかなり難しいのかということと、やはり今後こうした額が余りにも大きく違うと、普通の区民からしてみたら、これはかなり驚かれる数字かなと思いますので、今後の予測の精度をどうしていくのかということもちょっとお聞きしたいのですけれども。","respondent":"多並道路課長、溝口公園課長","answer":"ただ、もう一つのこの勝島歩道橋のエレベーターの工事につきましては、近隣の地元調整と、また工事ヤード等の仮設工事の変更があった関係で、来年度の工事につきましては、元々の予定よりも６カ月ほどおくれる工程になりますが、ただ。当然、今年度、平成３０年度については減額という形になりますが、来年度、その分増やすといった形での対応を考えているもので、全体計画の中では、当初３年間で割り振った形での計画をしていますが。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"続きまして、各課の職員給与費についてお伺いいたしますけれども、各課の職員給与費、増えているところもあれば減っているところもあると見受けられるのですけれども、その理由は、人員を増やしたことによるものなのかということと、減らした理由、増やした理由、それはすなわち事業として力を入れたい課だから増やしたのか、逆にそこまで需要がないから減らしたのか、その増減の理由をお聞かせください。","respondent":"黒田人事課長","answer":"当初予算の編成ですが、平成２９年１０月１日現在の現員で当初予算を組んだ関係上、もちろん平成３０年４月に人事異動がありますので、例えば定年退職の方がそのままフルタイムで残られますと。","id":"exchange-044"},{"speaker":"筒井委員","kind":"意見","question":"そういった複合的な理由で細部が変わっているようなのですけれども、では、５３ページの文化観光費の文化観光課職員の給与など、ここが結構増えているかと思うのですけれども、その理由は何なのかということをお知らせください。","respondent":"黒田人事課長","answer":"文化観光費の人件費の増ですが、こちらは事業拡大に伴う増ということもありますが、育休の職員がおりまして、育休代替の職員を配置したとか、あと派遣職員がいたりということで、この所属における職員数が増えたということで、人件費が増えているです。","id":"exchange-045"},{"speaker":"筒井委員","kind":"意見","question":"それに対して、７１ページの学校職員の給与費は、これは結構減っていると思うのですけれども、その理由はどういうことなのか、お聞かせください。","respondent":"黒田人事課長","answer":"学校の職員につきましては、用務職員について退職不補充としていますので、現員分について、人件費だけとなるというものです。","id":"exchange-046"},{"speaker":"つる委員","kind":"質問","question":"６０ページ衛生費、６２ページ土木費、６４ページ河川下水道費、６８ページ公園管理費について伺っていきます。衛生費ですが、昨年の第３回定例会一般質問でも伺いました、小児がんなどの治療で免疫を失った子どもの定期予防接種の再接種の費用助成について伺っていきたいと思います。これは全１,７４１自治体が回答されたということでありますが、これに対する回答について伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"小児がんなどの治療により、一度免疫をなくした方々への予防接種の対応ということですけれども、今現状ではそういった方を対象とした予防接種の助成はございませんが、今後については検討を進めていきたいと考えております。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"昨年の一般質問でも質問させていただきまして、そのときにいろいろ事前に品川区の実施状況を確認する中で調査をしていただいた結果として、もう既に１年またいでいますから１昨年になりますけれども、初めて１件、品川保健センターに対してそのような問い合わせがあり、当時は品川区としての制度の用意がないので実施できておりませんということで。","respondent":"鷹箸保健予防課長","answer":"いつからという時期についてのお尋ねですが、現時点ではいつからということを確実に決めているところではございませんが、必要な方への対応ということで、実施の方向について改めて検討を進めていきたいと考えております。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"文京区は、今年の１月からということで報道でも確認させていただきましたけれども、そういう年度途中での実施ということも当然あるかと思いますし、予算化せずともいろいろな取組みの中でできることがあるだろうと思いますので、そこについてもう一段ご答弁いただければと思います。","respondent":"鷹箸保健予防課長","answer":"繰り返しの答弁になりますが、現時点ではいつからということをお答えできないところではありますが、実施に向けて検討していきたいと考えております。","id":"exchange-049"},{"speaker":"つる委員","kind":"確認","question":"河川下水道費でありますが、マンホール、ゲリラ豪雨とか台風によるマンホールからの噴き上げ対策というところで、これは具体的に対応を河川下水道課にお願いをして東京都と連携をして、先日２月２４日に工事をしていただいたところに関連して伺いたいと思うのですが、かむろ坂の不動前駅通り商店街から出てくるところが、昨年の９月１７日だったと思いますが。","respondent":"持田河川下水道課長","answer":"空気が抜けることそのものはなかなか抑えられないところですが、新しいそういった装置を入れたです。なお、これにかかった経費ですが、下水道局のほうに確認しましたところ、２００万円から３００万円の間ぐらいというように伺っております。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"６２ページ土木費に関連してですが、これは前から言われている場所でもあるのですが、桐ケ谷通りの歩道について、あそこはいろいろな経緯があってさまざまな課題もあるかと思いますが、特に私も過去、ちょっといつお伝えしたか確認しきれなかったのですけれども、ザンビア大使館のところのバス停のところなどは、電柱とバス停の停留所の看板があって、非常に人が行き来しづらい。","respondent":"多並道路課長","answer":"そういう意味では、今の委員がおっしゃったような電柱とか、いろいろそういう部分も含めながら、現在無電柱化事業につきましては、今年度、来年度と２カ年かけて検討することもありますので、区全体の中でその無電柱化も含めて検討していきたいと思います。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"次に最後、これは確認だけですが、公園管理費について、スクエア荏原の前の公園でありますが、その公園は町会等で避難訓練を行っていただく際に、平塚橋交差点側に抜けるスロープをつくると災害時の利便性が向上するのではないか。","respondent":"溝口公園課長","answer":"現在１ルートは確保されている状況ではありますが、今後の災害時の利用等を考えると、必要な部分はあるかと思います。ただ、公園ができたばかりになっておりますので、公園改修の時期、また今後の改修時期を考えながら、スロープの設置は考えていきたいと考えているところです。","id":"exchange-052"},{"speaker":"横山委員","kind":"確認","question":"私からは、５８ページ児童福祉費についてお伺いをいたします。幼児教育無償化についてなのですけれども、現在国からはどのような案が示されていますでしょうか。確認なのですけれども、０歳から２歳児の低所得者世帯のお子さんにつきまして、品川区での保育料の現状と、３歳から５歳児の助成を受けている割合を教えてください。","respondent":"佐藤保育課長","answer":"実施の効果につきましては、国としては２つ示しております。１点目といたしましては、子育てや教育にかかわる費用負担の軽減を図ることで、少子化対策とすること。","id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"「のびのび育つしながわっこ」の部分の理念と重なるということで、国が示します研修ガイドラインがあるかと思うのですけれども、品川区では改訂版の第４版「のびのび育つしながわっこ」や「のびしなプロフェッショナルスクール」など、今後の無償化に伴って保育士の専門性の向上の取組みについて予定しているかと思うのですけれども、このあたりをお伺いできればと思います。","respondent":"佐藤保育課長","answer":"幼児教育の無償化に関する今後の準備ですが、先週来から国や都のほうから順次細かい指導が提示されておりまして、今後区といたしましては詳細の事務処理を詰めるとともに、条例の改正や補正予算の検討、保護者への周知、電算システムの整備等を順次進めてまいります。","id":"exchange-054"},{"speaker":"横山委員","kind":"質問・要望","question":"平成３４年４月開設予定で、区の児童相談所の設置に向けた準備を進めているかと思いますが、児童相談所の開設後には、未移行幼稚園や認可外保育施設などの指導監督など、都と区の役割分担について変更などはあるのでしょうか。わかる範囲でお願いいたします。５年間の経過措置の期間の扱いについて、品川区のお考えをお聞かせください。","respondent":"佐藤保育課長、二ノ宮児童相談所移管担当課長","answer":"認可外施設に関しましては都の管轄ですが、区も身近な自治体として都に同行するなりして、情報共有と指導に努めてまいります。児童相談所を区が開設した暁には、いわゆる児童相談所設置市という形になりますので、その際に当たりましては児童福祉施設に関する事務、例えば先ほどお話がありました保育所等の設置認可、それから認可外保育施設に関する事務。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問・要望","question":"さまざま長期的にも準備が必要な部分があるかと思いますので、それぞれ進めていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問","question":"６０ページの第４款衛生費、第１項保健衛生費の中の３目保健予防費の感染症予防費に係わって、高齢者のインフルエンザ予防接種の自己負担金について質問をします。そこでお伺いいたします。つまり、高齢者の方のインフルエンザ予防接種が、目黒区では自己負担金がゼロのものが、品川区ではいまだに２,５００円という、つまり無料にできない理由は一体何なのでしょうか、お教えください。お願いします。","respondent":"鷹箸保健予防課長","answer":"そのため、品川区では高齢者を対象とした予防接種につきましては、あくまでもご本人が受けたいということと、受けたことによる効果、それから一部の副反応などについても十分ご理解をいただいた上で、一部自己負担をしていただいた上で接種していただくということで。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"そうしますと、今後も高齢者に対しては無料にする予定は考えていないということでしょうか。","respondent":"鷹箸保健予防課長","answer":"現時点ではそのように対応してきております。今後につきましては、また改めて考えることがあろうかと思いますが、現時点では高齢者の予防接種については自己負担をいただいております。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"努力義務とかそういうことでありますけれども、区民全体の健康増進とかそういう観点から考えれば、やはり高齢者のほうでもどんどん予防接種を受けていただいて、健康増進という観点から予防接種を受けていただく方向に誘導することを考えてもいいのではないかと思うのですけれども、その点いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"繰り返しの答弁になりますが、現時点では高齢者については一部自己負担をいただいております。今後についてはまた改めて検討することになろうかと思います。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問","question":"高齢者の方を無料にするのにかかる金額というのは、大ざっぱでいいですけれども、どのぐらいかかるのでしょうか。","respondent":"鷹箸保健予防課長","answer":"今、おおむね接種にかかっている費用の半額をご負担いただいておりますので、すぐに積算が出てこなくて申しわけないのですけれども、おおむねその倍の費用がかかります。毎年の接種率にもよりますけれども、決して少ない金額ではないということはお伝えできるかと思います。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"ちょっと議事録を見まして、数年前にうちの議員が質問しているのですけれども、例えば６５歳以上の高齢者が実際に全員この予防接種を受けてるわけではないわけですよね。その議事録によりますと、例えばその年にたしか３万３,０００人受けていたと思うのですけれども、そうすると２,５００円掛ける３万３,０００人で、８,２５０万円の予算になると思うのですが、そのぐらいの感じでよろしいでしょうか。","respondent":"鷹箸保健予防課長","answer":"経費についてはその倍かかっております。","id":"exchange-061"},{"speaker":"おくの委員","kind":"意見","question":"だから、６５歳以上で３万３,０００人が予防接種を受けていたとして、それを２,５００円払って受けているのだと思うのです。その２,５００円を無料化すれば、８,２５０万円区として新たに負担しなければならないという理解で多分よろしいのだと思うのですけれども、だとしたらその程度の予算でできるのだということだと思うのです。","respondent":"鷹箸保健予防課長","answer":"数字としてはおおむねその額かと思います。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問・要望","question":"大体そういうふうに１億円もかからないような予算でできる話なのです。予算的にはその程度のものですので、私としてはやはり早急にやっていただきたいと思います。もちろん、目黒区は３分の２程度の人口ですから、品川区が同じ予算でできるとは思いませんけれども、ほんのわずかな予算できることですから、なるべく早急に実現していただきたいということを要望しまして、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"大倉委員","kind":"質問","question":"私は、３７ページの武蔵小山周辺地区再開発事業に関連して、お伺いできればと考えています。もう一点、５９ページの私立保育園費もしくは新規開設助成費なのですが、今、日中子どもたち、保育園の小さいお子さんたちを公園に移動させるために大型ベビーカーなどが利用されていると思いますが、こうしたものへの助成の費用というのはどこに入っているのか教えてください。","respondent":"稲田都市開発課長、大澤保育支援課長","answer":"そういう中で、東急電鉄も現状は把握していますので、今後も協議をしながら、６両編成のところを８両編成にしていきたいという東急の検討はあるようですけれども、その辺も引き続き協議していきたいと思います。私立保育園費の大型ベビーカーの件ですけれども、これは予算書上では区内私立保育園経費の運営費の中に含まれておりまして、基本的には運営費、大体園で平均で１億５,０００万円ほどお支払いしておりますので。","id":"exchange-064"},{"speaker":"大倉委員","kind":"質問・要望","question":"６両を８両にしていくということは、いつぐらいまでにどのようにできていくのかというのがどこまで話されているのか、わかれば教えていただきたいのと、これは平成２８年度の国のデータなのですが、混雑のデータということで、品川区だと目黒不動前が１７０％と都内でも１８位ということで、かなり混雑しているということがデータとして出ているのですが。","respondent":"稲田都市開発課長、大澤保育支援課長","answer":"ただ、広域的に他社の乗り入れもある路線ですから、他社との調整が非常に難しいというようなことを言っておりました。ただそうは言ってもこういう協議をしながら、その辺の解決に向けてやってくださいということは言っているところです。私立保育園の運営費につきましては、公定価格のほかに、区の加算として１園当たり５,０００万円程度の加算をしておりますので、その中で必要なものを買っていただくのが基本と考えております。","id":"exchange-065"},{"speaker":"大倉委員","kind":"質問・要望","question":"保育園の費用ですが、わかりました。最後に簡単に確認なのですが、６５ページの勝島歩道橋エレベーターなのですが、歩道橋にエレベーターが設置されている数はどのくらいあるのか、わかれば教えていただきたいのと、改めて国道等にかかる歩道橋について、これから改修を行っていくのか、撤去なのか、国や都の動向を教えていただきたいと思います。","respondent":"多並道路課長","answer":"それにつきましては、品川区の長寿命化計画の中で修繕したり、また改修したりということで、適切に維持管理していく予定です。エレベーターにつきましては、現在８基６カ所あります。それにつきましても、維持管理を適切に行っているところです。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は６３ページ感染症対策事業から、先天性風しん症候群対策についてお尋ねいたします。現在、風しんと麻しんが同時に国内で流行している状況です。このうち、本日は風しん流行と風しん対策についてお尋ねしたいと思います。現在、２０１９年２月までの風しんの流行状況について、簡単にご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"風しんですが、昨年７月以降、感染した患者が増えておりまして、昨年と今年の２月１７日、第７週までを合わせまして３,４４５名の方が風しんということで届出がありました。","id":"exchange-067"},{"speaker":"鈴木（博）委員","kind":"提案","question":"ご説明ありがとうございました。私はその方策として、２０歳からの健康診査の対象者、そして今回、国保基本健診対象者にも通知を同封することを、昨年の一般質問で提案しましたが、今回の厚生労働省の指針の中にも、国保基本健診の項目に風しん抗体検査を加えて、これを活用するようにというような厚生労働省からの通達があります。これに関してはどのように対応されるおつもりなのか、まず一つ伺います。","respondent":"三ッ橋国保医療年金課長、鷹箸保健予防課長","answer":"発送が４月中旬ですので、皆様のお手元に届くのが４月下旬ごろとなります。ＣＳＲ推進協議会および産業ニュース等についての対応ですが、ＣＳＲ推進協議会に関しましては、昨年１０月に臨時号ということで、関係企業の方に急ぎこの風しんに関しての注意喚起の情報をメールで流しています。","id":"exchange-068"},{"speaker":"鈴木（博）委員","kind":"提案","question":"２０１９年の２月４日のＮＨＫニュースのデジタル版によれば、企業が従業員に行う健康診断を請け負う団体が、今年の春の健康診断から抗体検査を新たに加える提案をし、大手航空会社など数社は既に実施を決め、検討中の企業も多数あるというニュースが流れました。それと、先ほどの今いろいろなことをされているというご報告があったのですが、ほかにも何かありましたらご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"企業健診ですが、今回の４月以降始まる風しんの追加的対策に関しましては、まず国からこういった健診機関に今回の取組みの重要性および企業健診でも、自治体。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"厚生労働省の「風しんについて」という解説によると、医療従事者や学校関係者、保育・福祉関係者など、風しんにかかる率が高い人が風しんにかかることで周りに多大な影響を与えると困るので、こういう職種の方が風しん抗体検査をぜひするべきではないかというメッセージがあったと思うのですが、品川区は昨年１１月に保健予防課と人事課が共同で、区職員に対して風しん抗体に関する調査をしたと思うのですが。","respondent":"鷹箸保健予防課長","answer":"昨年１１月の職員対象の取組みですけれども、妊婦ですとか乳幼児と身近に生活する職員については、記名式で結果を課長に報告する。予防接種を受けていない人は接種勧奨をする。それ以外の職員については、無記名でご自分で対応するというところで取組みを進めました。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"確認","question":"現在、南品川三丁目に建設中の障害児者総合支援施設についてですが、我が会派の代表質問で確認がありましたとおり、２０１５年にこの事業計画が発表されましたが、それによれば今年の２月に竣工して、４月から開設を予定していましたけれども、工期が半年間延長となって、今年１０月の開設となりました。これでいくのかどうか。これについての区の見解をお伺いしたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"地域との関係です。今までも、先ほど委員からお話があったとおり、品川児童学園ということで、地域との関係もいろいろ大切にさせていただいておりました。今回もこの施設をつくるにあたり、地域のほうにも昨年末になりますが、説明をさせていただいたところです。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これ、名称というのは本当に「名は体をあらわす」で、この施設は一体何の施設なのですかと私は散々聞かれます。ぜひお考えをいただきたいと思います。私としては、そもそもやはりアール・ブリュットというところが一つの特色ということで説明を受けていまして、それで了承してきた部分があるので、ここについてもう一度確認をさせていただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"こちらの施設は委員のおっしゃるとおり、職と医療と文化ということで、大きな３本の柱で提案もいただきました。アール・ブリュットというのは、もちろんこちらのほうでも引き続き展示も行ってまいります。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問","question":"前にご答弁いただいた中には、今回そういうことでアール・ブリュットの国内の雄として取り組まれている愛成会と一緒にやるというところだったので、そこについては課長にも少しお伺いしたいのですけれども、アール・ブリュットと障害者の芸術の違いについて簡単にご説明いただいて、そしてどのようにアール・ブリュットを展示していくのか、ご説明を受けたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"障害者の作品となりますと、何かしら障害のある方がやはり自分の気持ちをあらわしたり、そういうところで自分の内にこもっているものを表現したりとか、そういう性質の作品かと思われます。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこでアール・ブリュット美術館と名を付すからには、今後はやはりある程度の予算を組んで、一定の場所を確保して、いわゆるそういうところの展示、貸し出すだけの展示ではなくて、そういうものを一つ方向性として、アール・ブリュット美術館としての方向性を必ず打ち出していただきたいと思うのですが、ここについていかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"そういう方の作品もここではまた紹介できて、また新たな作品の展示等にも利用できればと考えております。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"基本的には努力義務です。いくらいろいろな指定管理の方法が変わったとしても、それは利用者にかかわってくることなので、そこについて、最後にこうしたことの先ほど申し上げました障害者の文化芸術活動も含めて、最初に３つのことでやっていくという打ち出しを私ども受けましたので、そこについてしっかりとやっていくということの最後の決意をお伺いしたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"芸術活動の推進ということでは、この４法人は最初から言っていますように新しい風を取り入れるというところでは、４法人が連携して行うことは今までと変わりませんので、期待して一緒にやっていきたいと考えております。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"私からは、６９ページの広町地区整備検討委託にかかわって、区民参加、情報公開について質問します。補正予算で１,４００万円減額されていますが、事項別明細書では委託内容の変更があったとのことですけれども、どういう変更なのか伺います。","respondent":"稲田都市開発課長","answer":"現在調査検討を行いながら、さまざまな課題を整理しているという状況ですが、新しくまちづくりを考えていくために、重要なものは都市基盤、特に道路の検討、それから区有地とＪＲの土地がいわゆる飛び地のような形になっているため有効な土地の利用の検討、歩行者の動線。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。しかし、現在の進め方は、区庁舎はどうあるべきかという区民の議論を置き去りにして、ＪＲが進めたいとする再開発計画がまずあって、その中で庁舎をどうするかという逆立ちした議論になっています。図面も課題を挙げた１４１カ所全てが黒塗りになっています。なぜ公開できないのか、区民参加のために公開すべきと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"現在ＪＲとの共同検討等をやりながら、どのような計画を立てることができるのか、可能性につきまして調査検討を行いながら課題の整理を行っているという段階です。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"地方自治体の意思形成は、そもそも主権者である区民自身が行うべきであり、意思形成過程であることを理由にして非公開とすることは、情報公開制度の趣旨に反することになります。意思形成段階の情報公開こそ、積極的に区民に公表し、意思形成に関する区民参加を進めるべきです。意思形成過程の情報こそ公開すべきだと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"区といたしまして、議会や区民の皆様へ必要な情報等の提供は、これは当然のことです。今後も本地区を検討していく過程におきましては、区として示すべき時期が来た段階で、皆様方への情報等を出していきたいというものです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"意味がありません。区民参加で進めたほうがよりよい案がつくれると思いますけれども、この庁舎は職員はもちろんですが、区民も利用するものであり、住民福祉の向上のためにも使いやすくわかりやすい庁舎にすることが求められます。この意思形成過程の情報を公開して、区民参加で進めるべきだと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"ましてや高低差もあります。非常にこういう部分におきましても検討課題が多いということで、先ほども言いましたけれども、調査検討を行いながら課題の整理を行っている段階ですので、区として示すべき時期が来た段階では、皆様方に情報を出していきたいです。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"これまでも他自治体の例を紹介していますけれども、立川市では庁舎の基本構想を策定する際に、公募市民６５人と各種団体から４３人と委員長などから成る市民１００人委員会を立ち上げて、市は敷地と建物規模、建設費、スケジュールのみを提示して、白紙から庁舎がどうあるべきかを市民の検討に委ねました。この区民参加で進めることを検討したのか、検討しなかった場合なぜ検討しなかったのか、伺います。","respondent":"立木経理課長","answer":"その中でどのような形が望ましいかというのは、検討する中で必要な意見の取り入れ方につきましては、議会の意見を伺うとともに、さまざまな手法を用いてまいりたいと考えております。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"声の取り入れ方はさまざま検討するということですけれども、それをぜひ検討段階から声を取り入れていただきたいということを言っていますので、そういったことをやっていくのか伺います。","respondent":"立木経理課長","answer":"現段階では隣に大きな土地があるというところでは、ひとつ候補として、先ほどから答弁させていただいているとおり、今検討させていただいている中で、必要な機能等、これから課題の整理等をする中で、いろいろな手法で研究してまいりたいと考えております。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"具体的な答弁がないのですけれども、この間、答弁の中で意思形成段階ということで、まだ決定していない状況だから公開できないということですけれども、現在の課題も公開できないということはどういうことでしょうか。課題は今こういう問題があるという事実だと思います。この事実を公開できない理由は何か伺います。","respondent":"稲田都市開発課長","answer":"例えば下水道に関しましても、この地区は現状の下水道しか通っておりませんで、今後まちづくりを進める上では、どのような形で下水道を通すかとかいうようなところを今さまざまに検討しているという段階ですので、現状を報告するにも課題があるので。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"現在調査中なので公開できないということですが、その調査が終わるのはいつでしょうか。","respondent":"稲田都市開発課長","answer":"さまざま今までもやってきておりますが、これはＪＲと共同検討する中で、どこをどう通したほうがいいとか、そういう話を並行しながらやっているところです。全てが関係していますので、示すべき時期が来た段階で公開していきたいと考えています。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"実態がよくわかりませんでしたけれども、ぜひこの新庁舎検討は区民参加で進めていただきたいということを強く要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"渡辺委員","kind":"質問","question":"６５ページのヒカリの水辺プロジェクト、６９ページのしながわ区民公園、東品川海上公園。主に水辺のシリーズとして質問させていただければと思います。そういう前提で伺います。予算のところ、減額になっている。特に項目ごと、ヒカリの水辺プロジェクト、しながわ区民公園と東品川海上公園、それぞれの減額理由、主な点でまずお知らせください。","respondent":"持田河川下水道課長、溝口公園課長","answer":"ただ、予算の要求の段階で少し規模が大きく、これ以外の橋りょうも含めて大きな工事として出すという形で予算を今年少し多めにいただいたところですが。東品川海上公園につきましては、先ほど河川下水道課長から説明もあったように、用地買収をして、その後工事まで進む予定だったのですが、用地交渉の結果今年度に改修できないことに伴い。","id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問","question":"されど、ただいろいろ期限がありまして、地域の期待もありますので、そこから伺ってまいります。スケジュール感のところで言うと、オリンピックをどうしても意識した中で、２０２０年、特に京浜運河のところ、もちろん今区の施策で、五反田から天王洲は着々と進んでいる。おそらく多くの方もそう思っている。これは区だけでは取り組めない部分がありますが、その辺の認識を教えてください。","respondent":"持田河川下水道課長","answer":"さまざまなことを提案させていただいてございまして、かもめ橋、勝島橋、スケジュール感としましてはやはり１２月というのを一つの目標といたしまして、ライトアップのほうを進めていきたいと考えています。","id":"exchange-086"},{"speaker":"渡辺委員","kind":"質問・要望","question":"具体策をどう盛り込んでいけるかというタイミングなので、幾つかまたご要望をこの場でもします。今の橋の２点。そのような道筋はいかがですかというのが１つ。この辺のお考えを教えてください。それと同時に、品川区ならではの施策の中で、子どもたちが安全性も踏まえた中で水辺の環境学習ができるような空間、そのような拠点を地域からも要望いただいていますが、考え方を教えてください。","respondent":"持田河川下水道課長、溝口公園課長","answer":"今年度先行的に実は進めてあります目黒川の橋りょうなどでは、今ライトを光らせるというところは技術的なところですが、色の部分もさまざま変えられるということで。一部埋め立てして広場等を整備するところですし、あわせまして、水質を浄化する観点もありますので、そういった中で噴水を入れた水質浄化施設といったものも整備していきたいと考えておりますので、貴重な水辺の空間ですので。","id":"exchange-087"},{"speaker":"吉田委員","kind":"確認","question":"移動支援事業、ガイドヘルパーの利用が伸びたということで、予算のほうも確認しましたが、今年度より１,０００万円以上増えています。要綱の変更も確認しました。要綱には、確かに同行援護を優先すると書かれておりまして、それは当然だと思いますが、同行援護が使えない部分については、支給基準の範囲で移動支援が使えるのではないかと思いますが、その辺についての見解を教えてください。","respondent":"松山障害者福祉課長","answer":"その実態に合わせて内容を改正したものです。２点目です。同行援護のほうで使えない部分については、移動支援の中で支給するです。そちらは、ご指摘のとおりですので、要綱に照らし合わせて、あとは個別のご事情とあわせて、支給してまいりたいと考えています。","id":"exchange-088"},{"speaker":"吉田委員","kind":"質問・要望","question":"その下も、「等」がついたその一文字は大きいかなと思っておりまして、放課後デイの送り迎えとありますけれども、放課後デイは割と送り迎えを事業者のほうでしていたりして、例えば「すまいる」はどうなのでしょうか。それも使えるのか、確認させてください。後で見解を教えていただければと思います。次に生活保護費のほうに行きます。生活困窮者自立支援事業の減について確認をさせていただきました。","respondent":"松山障害者福祉課長、矢木生活福祉課長","answer":"２点目ですけれども、シルバー人材センターでマッサージというのがどういったような解釈なのかですけれども、こちらは経済活動として見るのか、あるいはボランティアとして見るのか。相談員の件につきましては、こちら年度途中で辞められたために、ちょっと補充ができなかったということで、来年度につきましては、しっかり人員を補充して対応してまいります。","id":"exchange-089"},{"speaker":"吉田委員","kind":"質問・要望","question":"それについて、移動支援が使えるのであれば、ぜひそれを皆さんに広めていただきたいと思います。生活保護のほうです。品川区は、もともとこのスーパーバイズ機能、品川の家計相談に取り組んでいますので、使えるのだと思うのですけれども、今までこの機能を活用してこられたのでしょうか。もしあるようでしたら、その事例は何件か教えてください。","respondent":"矢木生活福祉課長","answer":"こちらのスーパーバイズ機能ということなのですが、今までご相談に来られた方をご案内したということはあったのですが、要件が合わなかったようなので、今まで支給の実績はございません。","id":"exchange-090"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。ぜひ専門性がある団体を使えるのであれば、区とそこと連携して事業を進めていっていただきたいと思います。それから、連携という意味では庁内の連携が気になります。そこがまた東京都のスーパーバイズ機能と連携しているのであれば、払えるようにするという相談を実質的にやるのは、生活困窮者窓口のほうではないかと思うのですけれども、その点の連携について教えてください。","respondent":"矢木生活福祉課長","answer":"今までも私どものほうで、生活困窮者自立支援制度運営協議会というところで１８課連携して行うということで、課長級を中心に組織し、そして具体的な事案については各課で連携して行ってまいりました。","id":"exchange-091"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり今払えないという相談に来た人に対しては、払えるようにするための家計診断は絶対欠かせないと思います。スーパーバイズ機能もあります。ぜひ庁内での連携を図っていただいて、きちんと払えるような具体的な相談に結びつけていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"高橋（し）委員","kind":"質問","question":"先に特別区税についてお伺いします。次が世田谷区、葛飾区の１.３％のプラス。ということは、これは特別区税が減る、そこを決算額と比較して減ってくるのではないかというような見込みなのですが、弱気という言い方がよくなければ慎重という言い方なのかもしれませんけれども、こういった見込みで特別区税の予算を品川区として算定、見込んでいるということについて、どのようなお考えがあるでしょうか。","respondent":"伊東税務課長","answer":"ただし、今委員ご指摘の平成２９年度の決算のところですけれども、以前にも話をしたかと思いますけれども、一時的に大口の納税の部分があって、それがなくなった関係で、全体で見れば伸ばしていくつもりだったのですけれども、その大口の部分を除いて考えてみますと。","id":"exchange-093"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは、結局最終的に決算したときには、金額的に最終補正よりもかなり多くの金額になるわけです。これは、おそらく決算後を考えてみれば、また同じようにプラスに出てくると思うのですが、今の２３区平均ぐらいの、強気という言い方が正しいかどうかわかりませんけれども、実態をもう少し把握していらっしゃったら、特別区税はもうちょっと多く入るという状況で予算を編成してはいかがでしょうか。","respondent":"伊東税務課長","answer":"今回補正ですけれども、確かにいろいろな形で伸びているというところで、そういうのも本来的にはもっと見込みをしっかりとというようなところかと思います。ただ、金額が大きい中でその収入率とかの関係もありますので、その辺は若干どうしても固く見ざるを得ない。","id":"exchange-094"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話があったように、見込みをしっかりとしていっていただくということがご答弁にありましたので、ぜひそちらのほうはお願いしたいと思います。これは要望しておきます。教育費のほうで、教育推進費が７８２万円だった積立金が一気に５０億７８２万円ということで、補正で５０億円積まれたということであります。余りにも非常に突出しているというところなので、この辺のご説明をお願いします。","respondent":"品川財政課長","answer":"教育関係の基金です。基本的には毎年３０億円程度の積立になっているのですが、昨今、これは基本的には学校改築関係を中心として積み上げているものです。やはり最近どうしても校舎改築、人件費等の高騰とかもありまして、金額的にも大分上がっているというような点があります。","id":"exchange-095"},{"speaker":"高橋（し）委員","kind":"質問","question":"平成３１年度の予算でも１００億円を使うということがありますので、今のお話は理解できるのですが、そうでしたら、どうして当初予算で７８２万円しか積まないのですか。それは、先ほどの特別区税を低くというか、慎重にというか固くしたところからも出てくるのではないかと思いますが、当初予算で、今は毎年３０億円ずつ積んでいるというご答弁ですから、なぜ積まなかったのかというところをお願いします。","respondent":"品川財政課長","answer":"基本的にこの補正のほうである程度歳入のほうも見込みが見えてきているという中で、年度末の補正予算に対して、今回５０億円という形で積む形にしています。","id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"ちなみに、品川区の景況、平成３０年１０月から１２月、これが今、直近だと思うのですけれども、「低調感がやや強まった」、「やや改善する見込み」、これは何だという感じなのですけれども、ここのあたり、国でもインバウンドに向けて、平易な表現に戻しましょう、変換をしましょうという動きがある中、中小企業あるいは商業のまちとして、景気動向の表現がこのような形でよいのかということを。","respondent":"山崎商業・ものづくり課長","answer":"景況調査は通常、３カ月単位で行っているです。そうした関係もありまして、例えば今期を表現するときには、前期の状況からよくなった、悪くなったという表現を実は使います。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"まさに今、課長がおっしゃったような表現を私は欲しているわけであって、そのような表現に変えるようなことというのは、いろいろな制約の中で可能なのでしょうか。それとも、難しいのか。ここのところは改善の余地があると私は思うのですけれども、どのように考えますか。","respondent":"山崎商業・ものづくり課長","answer":"そうしますと、アルファベットの始点と終点は、始まって、おりて、戻って、落ちて、また戻るということで、横にしますと、リーマンのころのＤＩ値に戻っているという状況が見てとれるグラフなどもつけて、ご説明できるようにはしています。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問・要望","question":"ただ、メリットに関しては、ここの景況調査にもありますように、小売業だったりサービス業だったり、先行きがあまり芳しくない業種にとっては、休みというのはとりわけ商店、商店街にとっては追い風になってくるんですけれども、ここについて品川区は、直近ですけれども、ゴールデンウイークあるいは１０連休についての中小あるいは零細企業に対する対策を、何か今までお考えになって。","respondent":"山崎商業・ものづくり課長","answer":"ただ一方で、中小企業でいろいろ仕入れをして、ご商売のために製品を納品するとかという意味では、納期の関係ですとか、その辺の資金の回しがちょっと大変だ、考えなければというようなお声も同時に伺っております。双方さまざま、いろいろなお声が届いているという状況です。","id":"exchange-099"},{"speaker":"大沢委員","kind":"質問・要望","question":"ですから、そこのところを十分にご斟酌いただきながら、今回の１０連休、終わったら検証していただきたいと考えています。こういう２つの大きな柱の対策が出ておりますけれども、ご家族経営のところと本当に小規模でやっているところは、この２つをとってしまうと、営業が成り立たなくなるような気がしてならないのですけれども、そこのところはどういうふうに見積もっていらっしゃいますでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"特にこれをというものは、区としましては、日ごろからの経営相談で臨機応変に対応するようなことをやっておりますので、こうした日々の経営相談を充実させつつ、万が一の急な資金需要に応えるべくさまざまな工夫をして、ご用意をするように対応していくつもりです。","id":"exchange-100"},{"speaker":"大沢委員","kind":"質問・要望","question":"意外と融資の部分に関しては、設備資金に関しては、比較的出やすいのです。運転資金は、本当に必要としている業種というのは、なかなか認められていないことが多々あると私は認識しておるのですけれども、そこのところをうまくかみ合わせることができるような施策というか、区の事業を展開していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"私からは、５３ページ、戸籍住民課職員給与費、主に住民票の交付についてと、ページの５７ページ、就労移行支援とか就労継続支援Ｂ型、この辺から障害者の就労について。時間がありましたら、６５ページのオリンピック・パラリンピック施設周辺等無電柱化事業について伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"住民票の交付に関する窓口の負担の割合ですけれども、戸籍住民課全体では、戸籍の届け出、住民の異動届、住民票の写し・印鑑証明の交付とか、主な証明交付事務というのがあるのですけれども、全体でいうと、はっきりとした数字は出ませんけれども。","id":"exchange-102"},{"speaker":"塚本委員","kind":"質問","question":"住民票についてなのですけれども、いわゆる住民票除票は、５年間保管ということがこれまで義務づけられていて、品川区も以前質問したときには５年間ということで、５年過ぎれば廃棄していますということでしたけれども、昨年からこの辺の議論が国でいろいろされて、総務省の有識者研究会というところでは、戸籍と同じように保存期間１５０年という報告書がまとめられたということもありました。","respondent":"提坂戸籍住民課長","answer":"それで、改正されましたら、もちろん国に従うしかないのですが、それまでに住民台帳の除票が、保存期間が過ぎてしまいますと、とれるものもとれなくなってしまいますので、これから除票になるものについては、とりあえず廃棄を待つという形で。","id":"exchange-103"},{"speaker":"塚本委員","kind":"確認","question":"わかりました。では今後、とりあえず除票は５年間という区切りは、ひとつ保留をして、おいておくというところで確認をさせていただきました。もう一つだけ確認なのですが、保存期間延長に伴いまして、戸籍住民課としての経費とか事務負担とか、そういうものは何か発生してくるのか、その辺で何か懸念するようなことがあるのかないのか、最後に確認させてください。","respondent":"提坂戸籍住民課長","answer":"それに対して自治体側としては、毅然とお断りしなければいけないのですが、その辺の負担が大きくなってきて、毅然と断らなければいけないという、その辺の加害者に対する対応をきっちりとやらなければいけないという負担が、ずっと半永久的に続くという懸念はありますが。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問・要望","question":"５７ページの就労移行支援、また就労継続支援Ｂ型というところなのですけれども、今、品川区におきましては、施設において就労継続支援Ａ型、Ｂ型というところで、各所でやられておりますけれども、ここで行われている主な作業の内容を、改めてご紹介いただければと思います。","respondent":"松山障害者福祉課長","answer":"Ａ型であれば、主に「プチレーブ」等のパンの製造等があります。Ｂ型であれば、一般的にはそれぞれ小物づくりだったり、自分たちの箱詰めの作業や、箱の製作等があります。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問","question":"素材もプラスチックだとか、金属だとか、いろいろな素材でつくれるみたいで、こういった新たな技術というのもうまく活かすと、障害者の方にとって非常に適した作業も生み出せるのではないかという思いも少ししておりますので、こういったことについて、ＩＣＴとか３Ｄプリンターとか、最新の技術を使った作業を、この就労継続支援の中で活用していくということについてのお考えをお伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"委員ご提案のＩＣＴや３Ｄプリンターなどを活用した就労継続につきましては、現在も発達障害をお持ちの方は、それが得意な方もいらっしゃいます。発達障害者支援センターでは、現在、スキャナーを使ったスキャン作業、それから簡単なデータ入力は行っているところです。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうやってできたものを、今度はつくり方とか、そういうのをインターネットの世界でシェアして、多くの人が共有するというメリットもあるということなので、非常に可能性のある作業かとも思っておりますので、新たな技術等も含めて、今後取り組みをぜひ検討していただきたいと思いますけれども、最後にもう一言だけ、そういった新たな最近の技術ということで、何か見解というところでお伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"新たな作業というのは、就労支援センターや作業所も、かなり模索を今現在、している段階です。そのため、個々の障害特性に合った、しかも作業となるというものを新たに創造して、作業所運営事業者とともに、一緒に考えていきたいと考えています。","id":"exchange-107"},{"speaker":"塚本委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。では続いて、６５ページのオリンピック・パラリンピック施設周辺等無電柱化事業のことで、少し金額が減になっておりましたけれども、まず、減の理由をお聞かせいただきたいと思います。","respondent":"多並道路課長","answer":"その道路整備をＩ工区、II工区と、２工区に分けて工事を行っていまして、そのうちのII工区のほうが、全体工事自体は変わらないのですが、平成３０年度、３１年度の執行の状況が変わってきて、今年度が少なくなるということで、減額させていただいて。","id":"exchange-108"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、勝島のほうがいろいろ、工事がやや難しいところが出てきたという話でしたけれども、期間的にとか準備的には、当初の計画どおりということで大丈夫なのかどうかということを、１つ確認させていただきたいのと、オリンピック施設の周辺無電柱化ということで、品川区で今、先んじてといいますか、進めていっていただいておりますけれども、一方で、今年の予算の中で、品川区の無電柱化に向けての。","respondent":"多並道路課長","answer":"今年度については、進めるための基本的な方針を定め、来年度に具体的な整備を進めるべき路線やスケジュール等を検討していこうという内容で、このような形で今後、計画的な無電柱化の進め方ということで、２年間かけて整備していきたいということになります。","id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成３０年度の予算を見ると、予算では１１億９,０００万円余となっていますけれども、結局これを見ると、法定外繰入は３億３,０００万円しか出していないということでいいのか、それであれば、なぜこんなに少ない法定外繰入の額になったのか、法定外繰入としては６％分、繰入を行うと言っていたわけですけれども、そうならないのではないかと思うのですが、いかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"その他一般会計繰入金につきましては、歳出に対する歳入の差です。こちらにつきまして、平成３０年度は平成２９年からの繰越金の分が多くなったことなどについて、その他一般会計繰入金は、委員ご指摘のような金額となっております。","id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結局、法定外繰入は３億３,０００万円ということで確認させていただいていいでしょうか。その均等割が、収入のない子ども、生まれたばかりの赤ちゃんにまでかかる仕組みが国保の制度ということで、国保だけがこういう仕組みになっているわけですけれども、これは私は、ほかの医療保険と比べても不公平な仕組みではないのかと思うのですが、それはいかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"平成３０年度の収納率ですけれども、まだ出ておりませんが、平成２９年度につきましては、９２.６４％となっております。こちらは２３区の中で１位となっております。東京都の収納率向上にかかわる取り組みの成績の交付金額ですが、１億６,３００万円となっております。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほかの医療保険から比べても不公平だと思うのですけれども、その点について、不公平だとは思わないのですかということをお聞きしましたので、その点についてお聞かせいただきたいのと、３０億円程度、平成２２年のときから比べても税金投入が減っている分、この部分が基金を増やすことになっているのではないかということもお聞きしましたので、その点についてもお願いします。","respondent":"三ッ橋国保医療年金課長","answer":"これは制度として成り立っているものですので、私どもは制度に基づいて対応しています。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、セーフティーネットとしてできている制度であるので、税金を投入するのは当然ということでできた制度ですから、そこのところは本当に不公平な仕組みだということを改めて申し上げておきたいと思います。それで、収納率が２３区トップなのですけれども、１２月に庁舎に、「滞納はさせない放置しない逃がさない」という垂れ幕がかかって、私は驚きました。","respondent":"伊東税務課長","answer":"今ご指摘の懸垂幕の件ですけれども、こちらに関しては、税務課で掲示させていただいているものです。これは、１２月が「オール東京滞納ＳＴＯＰ強化月間」ということで、その一環として、これを掲げさせていただいたというものです。","id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、「滞納は」ですから、これは滞納者に対して掲げている言葉になるわけです。これは本当に、助けを求めるサインでもあるわけです。そういうところを、こういう形で「させない放置しない逃がさない」、悪質滞納者と決めつけたこういう垂れ幕は、ぜひやめるべきだと思いますけれども、いかがでしょうか。","respondent":"伊東税務課長","answer":"「させない放置しない逃がさない」という言葉がございましたけれども、「させない」という中には、まず、納期内納付ということが原則ですので、それに向けての対応をしていくというのが「させない」という形。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は年の瀬に、本当にどうやって年を越そうかと悩んでいる方が、滞納者の中にはたくさんいらっしゃると思うのです。私はそういう垂れ幕は、もう二度とかけないということで、ぜひとも区として徹底をしていただきたいということで、強く要望します。時間がなくなってしまったので、介護保険のほうは質問できないのですけれども、最後に、今回補正予算の態度についても述べておきたいと思います。介護保険。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほども出ていました件です。先にマイスクールの件です。これは昨年も質問をさせていただいたのですが、去年も更正減額になっています。これが、なぜ更正減額になってくるのか、まずその点を教えてください。それから、障害児者総合支援施設。何年間か関ってきて、昨年の３定で債務負担行為をやって、ここで落としたりして、最終的に建築総額は監理費を含めて幾らになるか、もう一回確認をさせてください。","respondent":"大関教育総合支援センター長、飛田障害者施策推進担当課長","answer":"マイスクール運営費、４５５万円の減額についてのお尋ねですが、こちらは都の補助金を１０割そのまま頂戴しまして、指導員費に充てております関係で、そのまま丸々補助金の方で配分するという形になっています。監理費も含めて、およそ５４億円となっております。","id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"都の補助金、１０分の１０はわかるのですけれども、そうではなくて、去年も同じように聞いたのですけれども、補正になってしまう理由がなぜかという点で、お答えをお願いいたします。なぜかというと、先ほどの休憩時間に、ちょうど部屋へ戻ったところで、平成３０年度の品川区教育委員会事務事業の点検および評価報告書をもらいました。これからの方向性等、もう一度確認をさせていただきたい。","respondent":"大関教育総合支援センター長","answer":"マイスクール八潮が数年前はいっぱいになってしまったという形で、五反田、そして今年度は浜川も増えまして、拡充をする形で、さまざまなタイプのお子様のニーズに対応して充実させておりますので、今後ともさらに工夫をして努めてまいります。","id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そこがわからないので確認させてください。それと、復帰していただく中で、学校へ復帰してから、例えば高校へ進学していくのか、それともマイスクールの中で、進学まで積極的に取り組んでいっていただいているのか、その辺がどうなっているのか。それともう一つ、品川区内にも通信学級とか、いろいろな先に進むような学校があると思うのですが、そことマイスクールとの関係をもう一度教えてください。","respondent":"品川財政課長、大関教育総合支援センター長","answer":"適応指導教室等の補助金の関係につきましては、補助の募集がどうしても毎年４月か５月ごろになってしまって、そういった時期的な問題で、当初予算に出せないです。本来、卒業式を迎える前に、自分の所属する学校に復帰をして、高校受験もできるのが一番望ましいとは考えておりますが、なかなかそこまではいかないお子さんは、最後の卒業式までマイスクールを利用しながら、マイスクール。","id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問","question":"予算の関係はわかりました。それがわかっていなかったので。障害児者総合支援施設のほうです。これは、先ほどもちょっと出ていましたけれども、就労継続支援Ｂ型のレストランが入ると思うのですが、そこへお勤めになろうと思った方がどのようになっているのか、その辺を教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"就労継続支援Ｂ型の事業ですが、こちらは愛成会が行う予定となっております。愛成会はレストラン業務も入りますので、レストランのところでの業務、調理の提供や、その方に応じた、どんなサービスがその方に合っているかというところで、今後向き合っていくということです。","id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その分、就労する方にとっても大変でしょうし、上手に配置していただきたいということを感じています。それから、先日の委員会の中でも、手厚い支援をするということで、担当の方たち、法人の中の従業員でお勤めになる方の人数が多くなってくるという中で、その方たちも４月からお勤めになっていくのではないかと。そこに対して区は、何か特別な支援をしていくのかどうかを教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"それを含めまして、今回、１０月に本格始動するまで、職員の配置も４月から行うということなので、そちらの配置状況を見ながら、区としても人件費等を精査いたしまして、フォローをいたしたいと考えております。","id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害者施設、これだけのものができたので、いい運営をしていただきたいということを、これは要望とします。もう１点、先ほど大沢委員からもお話があったのですが、４月の２７日から１０日間休みの中で、区の中の運営はどういうふうに開庁して、各施設がどうなっていくのか、概略で構わないので教えてください。","respondent":"米田総務課長","answer":"暦の中で法律によって役所の閉庁日というのが定められており、基本的に１０連休となるのですが、今、全体の調整をかけている最中でして、区民サービスの低下を招かないように、開庁するところは開庁してということを調整中です。","id":"exchange-121"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そのお考えであるところが、私も何回も申し上げているのですが、啓開道路というのですか、品川区にも何本かあると思うのですが、そういった道路に対して、どういう感じで考えているか、あと、手法は共同溝型なのか、直接埋設型なのかというのがわかれば、教えていただきたいです。そういう中での執行率は、今どういう状況になっているのか。これはまとめてで構わないので、教えていただきたいと思います。","respondent":"伊東税務課長、多並道路課長、品川財政課長、高梨木密整備推進課長、長尾建築課長","answer":"区民税のところですけれども、まずは、どの層あたりが増えているかですけれども、納税義務者で見ますと、全体的に増えていて。はオリンピック・パラリンピック施設周辺の無電柱化の件ですが、道路整備工事がＩ期とII期と。７４ページの表記につきましては、こちらは正確にはカンマです。ご指摘ありがとうあります。以後、気をつけたいと思います。不燃化１０年プロジェクトの執行率についてお答えしますが、不燃化１０年プロジェクトは。","id":"exchange-122"},{"speaker":"いながわ委員","kind":"質問・要望","question":"もう時間もないので、款別土木費で、２０分ぐらい時間をいただいて、しっかりとその辺は質問してまいりたいと思いますので、何かが足かせになっているような部分を感じますので、また質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"本多委員","kind":"質問","question":"６７ページの４項都市計画費、２目木密整備推進費について伺います。不燃化１０年プロジェクトです。重複しますけれども、お願いします。実績見合いの減ということなのですけれども、この課題について、どう捉えているのか、まずお聞かせください。","respondent":"高梨木密整備推進課長","answer":"周知・啓発活動に努めてまいりまして、結果としては昨年度比２５％増ということで、昨年度よりも増えた件数を執行する見込みですが、予算額には残念ながら届かないといったところで。","id":"exchange-124"},{"speaker":"本多委員","kind":"質問","question":"目標を設定して、本当にご苦労が多いかと思いますが、よろしくお願いします。すみません、補助２９号線について伺います。声をかける手段ですとか、進め方について教えてください。取得率が５％未満ということですけれども、環六から環七までの大崎から東馬込の間、こういう取得率というのは、全体を見てパーセンテージを出しているのか、品川区のエリアだけで出しているのか、その辺を改めて教えてください。","respondent":"鈴木都市計画課長","answer":"補助２９号線の用地取得率ですが、２９号線は非常に長い区間となっておりまして、東京都で６区間に分けて事業が進められておりまして、その６区間の用地取得率も東京都から聞いているところです。一番低いところでは５％、一番高いところでは１６％の用地取得率です。","id":"exchange-125"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました。１６％、そんな高いところがあるのですか。それは品川区のエリアですか、それとも大田区のエリアですか。そのことを教えていただきたいのと、もう一つ伺うのが、網のかかっているエリアなのですけれども、対象の方というのは将来への展望があると思うのです。","respondent":"鈴木都市計画課長","answer":"取得率１６％の区間は、西大井区間です。それから、補助２９号線に係る権利者の方々への東京都としての働きかけ、あるいはアプローチですが、基本的には事業を始めるに当たって、用地測量、あるいは事業説明を全体的に行ってきてあります。","id":"exchange-126"},{"speaker":"本多委員","kind":"質問・要望","question":"ただ、その進め方は全くわからない状況ですので、その辺は丁寧に進めていただきたいと考えています。品川区のホームページ等も見ると、目標、今後のスケジュールとかが書いてあるのですけれども、なかなか見通しというものが伝わってきませんので、その辺の見通しについて、改めて教えてください。","respondent":"鈴木都市計画課長","answer":"そうしたさまざまな権利者に対して、区でも東京都に対して、丁寧な説明あるいは状況に応じた対応を、今後も求めていきたいですが、あわせて、整備の見通しですが、東京都は引き続き、平成３２年を目標に事業を進めているですが、一方では。","id":"exchange-127"},{"speaker":"本多委員","kind":"質問・要望","question":"本当に丁寧に対応していただきたいと思います。それで、網のかかっているエリアは、それぞれ皆さん当事者はわかっているはずなのですけれども、この道路が整備されて、沿道になる皆様方の相談窓口というのも対応されていると思うのですけれども、現時点ではどういう状況か教えてください。","respondent":"高梨木密整備推進課長","answer":"先ほど都市計画課長が答弁しましたが、まず道路の中の皆様、権利者の皆様は、東京都が設置する相談窓口で相談する体制が整っておりますが、道路にはかからないのだけれども道路の沿道になる、沿道３０ｍの範囲内は不燃化特区として。","id":"exchange-128"},{"speaker":"本多委員","kind":"質問","question":"状況を聞いたのです。その相談窓口がどのくらいの相談を受けているのか、状況を簡単に教えてください。すみません、最後にもう一つ聞きます。既に用地取得が済んだところが、アスファルト舗装されて、緑色のフェンスで囲まれております。区の返事待ちになっていると思うのですが、そういったところはいかがでしょうか。","respondent":"高梨木密整備推進課長","answer":"相談窓口の状況ですが、日々お客様の状況に応じて、毎日のように相談者が来ている状況ですが、状況といたしましては、例えば不燃化特区の中では今、全体で４５０件を超える除却申請をいただいておりますが、そのうち相談窓口にいらっしゃった相談者から申請に結びついたお客様は。","id":"exchange-129"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、５７ページの障害者福祉費から伺いたいと思います。共同生活援助、グループホームと、就労継続支援Ｂ型の、一般質問では区外の利用者を聞いたのですが、ここでは区内の利用者、グループホームと就労継続支援Ｂ型の利用者の数を教えてください。","respondent":"松山障害者福祉課長","answer":"区内の利用者ですけれども、まず、グループホームにつきましては、平成３０年度は、区内事業者数が１４で、平成３０年の１２月末で定員が９８名です。それから、就労継続支援Ｂ型ですけれども、区内の利用者数が２８５名です。","id":"exchange-130"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"グループホームの施設数と定員数は今言っていただいたのですけれども、区内の利用者は、この９８名ということでよろしいのでしょうか。確認をお願いします。そして、一般質問の中では、入所施設で区外を利用されている方が１６４人、通所の就労Ｂで８３人と、こんなに多くいることが明らかになりました。第５期計画に基づいて増設に向けた計画などがあるのか、どのような中身なのかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"そのため、具体的な設置数というのは、お示しすることは難しいというものです。第５期障害福祉計画につきましては、主に荏原地区も含めて、増設を進めてまいりますという形で明記しています。","id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"土地の確保云々と。増設を進めることは、ぜひ進めていただきたいのですけれども、一般質問でもあった、区外を利用されている方、入所施設が１６４人で、通所が８３人という方々がいるという状況を、問題と考えないのか、そして、改善が必要と思わないのかということも伺わせていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"ただし、全ての方のご希望には沿えない部分がありますので、沿えない部分につきましては、実際にご本人やご家族のご意見を伺いながら、できる限り努力してまいりたいと考えています。","id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこに反省はないのかということも一般質問では伺いましたけれども、ここを問題と捉えて、そして改善をさせていくということが必要だと思うのですけれども、土地の確保の観点から計画を示すことは難しいということですが、であれば、区でどれくらいの方がグループホームや就労Ｂを区内に設置してほしいと望んでいるかという要望を捉えられているのでしょうか。","respondent":"松山障害者福祉課長","answer":"既に入所している方につきましては、モニタリングや区分調査などの機会を捉えまして、ご意見を頂戴し把握するです。実際に、区内にグループホーム等をつくってほしいという要望はいただいておりますので、増設を進めていくです。","id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、区外にいる方は特に要望を聞いていくべきではないかと思うのです。ですので、他県を利用している、平成３０年の１２月のデータでは１６４人が区外の施設に入所されているということですけれども、こういう方々から要望を聞いて、増設計画を立てるべきだと思いますけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"ただ、この１６４名全員の方が区内をご希望されているわけではございません。したがいまして、区といたしましては、増設に向けて、きちんと土地の確保や近隣の方々のご理解を踏まえまして、進めてまいりたいと考えています。","id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"決定的に足りないのが施設の整備だということを、私たちも言わせていただいているのですけれども、全ての方が希望されているわけではないということですが、であれば、希望されている方がどれくらいいるのか、今、把握はされているのでしょうか。１６４人という数の中からでもいいですけれども、この中から具体的に品川区を要望されているという方が、どれぐらいいらっしゃるのでしょうか。","respondent":"松山障害者福祉課長","answer":"そのため、私どもは全くつくらないと言っているのではなく、増設に向けて今も努力しています。グループホーム整備費助成金等もつくりまして、それを活用して事業者を誘致するなど、今後も開設に向けて進めてまいります。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"だからこそ、常に要望を聞いていくということが必要なのではないでしょうか。ですので、きめ細かな需要の把握というのを進めるべきだと思いますけれども、いかがでしょうか。都の平均も下回る整備率です。ですから、そうした面からも、やはり改善が必要だと思いますし、需要をつかんで、２３区で最低の状況を改善させていく整備計画を明確にすべきだと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"ただし、建物となりますと、土地の確保等々、条件があります。近隣の方々のご理解も得ながら進めていくものですので、具体的な整備計画というのは非常に難しいですが、実際に増設に向けて取り組んでいるところです。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問","question":"区としては、これだけ必要と考えるということを、しっかり当事者から声を聞いて示していくということでなければ、品川区は改善させていっていないのかなと捉えられて当然ではないでしょうか。そして、数字上では最低というのは示されていることですので、それを改善させていくというのは、品川区に大きな責任があると思いますし、具体的に進めていくべきだと思いますけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"委員のおっしゃられるとおり、今も積極的に進めております。そのために今年度、民間事業所の就労継続支援Ｂ型が１カ所、精神障害者のグループホームが３カ所、開設したという実績があります。今後も積極的に進めてまいります。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いつまでに幾つつくるかという計画を、具体的に立てていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"若林委員","kind":"質問・要望","question":"一般会計については、５５ページの要介護度改善ケアが、今回６６２万円の増額補正ということで、ここら辺の実績、傾向をお聞きして、確認をさせていただきたいと思います。それから、１００ページの後期高齢者医療特別会計については、８３億円の後期高齢者医療特別会計の全体に対して、わずかという言い方が正しいかどうか、割合としては非常に少ない２,４００万円の補正にとどまっております。","respondent":"寺嶋高齢者福祉課長、三ッ橋国保医療年金課長","answer":"５５ページの要介護度改善ケア奨励助成事業に関しましてですけれども、まず金額としては、当初予算で１,８３８万円を見込んでおりましたが。後期高齢者医療制度ですけれども、こちらも当初予算よりは若干、被保険者数の減となっておりますので、同様に減額させていただきました。これについては、当初見込みの中で１割負担、２割負担、３割負担ということで見込みを上げて、それぞれやっていたのですけれども。","id":"exchange-139"},{"speaker":"若林委員","kind":"確認","question":"それぞれわかりました。結果として２,４００万円にとどまっているということで、この段階でこのぐらいの金額で、最終補正をしなければいけないのか、内容によって、ここはこの時期に国とか都の関係があるので、そこら辺のご説明を、もしダブったらすみません、確認します。","respondent":"三ッ橋国保医療年金課長","answer":"しかしながら、今後につきましては検討させていただきたいと考えています。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"私は３４ページ、特別区民税、これは政策的なことなので、企画のほうにお聞きしたいと思います。そして、７２ページの給与費明細についてお聞きしたいと思います。その中の職員数をお聞きします。特別区民税。このように補正で２３億円増えています。こういうことをずっと繰り返すのか、何か区で規制しなくていいのですか。こんなことを繰り返していていいのですか。区の施策をお聞かせください。","respondent":"柏原企画調整課長","answer":"これは全体の話としてありますので、いずれはそのトレンドの中で、品川区も考える時期が必ず来るとは捉えておりますけれども、そういった中で、いかに品川区が発展するかということで、そういったところも見ながらですけれども、人口。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"先ほどお話が出ていましたけれども、木密地域は品川区にも、まだたくさんあります。あいたらどうなるのですか。そうしたら、区の施策はとまってしまうではないですか。そのうち２世代、３世代住宅もできてくるでしょう。そうしたら、どうするのですか。行き詰まってしまうのではないですか。最後に小学校、中学校を建てるようなことになって、それでいいのですか。その辺についてどのようにお考えですか。","respondent":"柏原企画調整課長","answer":"そういうところで、増えたから施設を増やすというよりは、先を見て、どういった形で増えていくのか、これから国、都の動きなども見ながら、どう世の中が動いていくのかというのを一定程度確認といいますか、調査をしながら、区の施策を進めているですので、その場で。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"先ほども、品川区を選んでほしいというならば、毎回この委員会で待機児童対策、また子どもに対するさまざまな施設の支援、これは考えるべき時期に来ているのではないかと私は思います。一応、意見だけ申し上げておきます。もう１点お聞きします。職員定数が毎年出ていますけれども、それに対して、例えば休職中の職員、それから公益法人等に派遣している職員の方たちは、それぞれ何名ずついるのですか。","respondent":"黒田人事課長","answer":"その他、定数外になっておりますのは、育児休業ですとか、病気休業というところでございまして、育児休業者数は平成３０年４月１日では７３名で、病気休職者というのは２１名といった状況です。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"今の休職者数は、定数外なのです。定数外ということは、区で職員定数の数を我々は聞かされています。でも実際、本来ならその方たちも載せなければいけない。そして、派遣している方もきちんと載せなければいけない。それが本来、品川区で働いている職員数の総数ではないですか。簡単に補充できないから。だから、職員数が１,０００人だったら、１人抜ければ９９９人。これはどのように考えればいいのですか。","respondent":"黒田人事課長","answer":"職員の数え方ですが、基本的に総務省の定員管理調査等がございまして、職員のカウントの仕方には一定のルールがあるという中では、その中で減員しながらという中では、今申し上げた定数外職員は除きますし、通常の自主財源人員ということであれば、当然。","id":"exchange-144"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、今回の東京都への移管というのは、地方自治の確立からすると、少し逆行する形だけれども、品川区の見解をまず確認させていただきたい。それから、各区市町村との国保に対する意見反映は、現状、例えば後期高齢者医療特別会計のように、事務局や議会を設置していると考えるのですけれども、具体的に反映できる担保はあるのでしょうかということをお聞かせください。お願いいたします。","respondent":"三ッ橋国保医療年金課長","answer":"こちらは今現在、平成３０年度につきましては、委員ご指摘のように、３区がこの特別区の考え方から離脱しております。それは千代田区、江戸川区、中野区です。来年度につきましても、同様となっているものと言われております。","id":"exchange-145"},{"speaker":"伊藤委員","kind":"質問","question":"若干、質問に答えていないところがあるのですけれども、私たちの思いとしては、都移管の目的はわかるのだけれども、ただ同時に、各区は人口規模も財政も高齢化率も違うわけです。だから、それを何で同じにするのかという質問。そのことについての品川区の見解をしっかりとお聞かせください。それから、最近、人生１００年時代と言われます。後半の部分は、違う担当の課長がいいと思うのですけれども。","respondent":"三ッ橋国保医療年金課長、寺嶋高齢者福祉課長","answer":"今までずっと平成１２年より、またもちろん、考え方としては昭和３４年時代からずっと統一してきたという経緯がありますので、こちらに賛同しているものです。高齢化率が高まっていること、それから寿命が延びていることにつきまして、介護保険事業といたしましては、まず、住みなれたまち、我が家で暮らすという、品川区には目標があるわけでございまして。","id":"exchange-146"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、前高橋区長の時代には、随分と言われました自治体間の競争、その具体化の一つがこれだと私は思うわけであって、そうすると、今の仕組み上は理解できるのだけれども、品川区の方向性としては、もう少し先のお話をさせていただいたら、これから人生１００年時代と言われている中にあっては、何も２３区で一緒に行く部分と、そうではなくて各区別の部分があってもいいと思うのだけれども。","respondent":"三ッ橋国保医療年金課長","answer":"区といたしましては、例えば医療費の適正化につきましては、データヘルス計画の中でさまざまな、三師会であったり関係部署と話を重ねて、医療費の適正化については対応してまいっているところです。","id":"exchange-147"},{"speaker":"伊藤委員","kind":"質問","question":"気持ちはわかるけれども、２３区そこまで仲よくしていく必要はあるのですか。そうではなくて、特色はある。よくシティープロモーションとかで言っているのは、品川区の魅力を打ち出すとおっしゃっているわけではないですか。だけれども、先ほど言ったように、これからこういう社会保障制度を充実していくに当たっては、こういうことも具体的に検討していく必要があると思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長、寺嶋高齢者福祉課長","answer":"ただ、今後の流れの中で、品川区がどういった形がとれるのかというのは、もちろん施策を進めていく中で、いろいろなところを考えていかなくてはいけないというところはありますので、今すぐ国保制度に対して。したがいまして、例えば元気高齢者のための事業であるとか、予防事業といったものの充実をあわせて行いまして、使わずに済むものは使わないで。","id":"exchange-148"},{"speaker":"石田（し）委員","kind":"確認","question":"私からは、補正予算全体についてと、５１ページ、住民情報システム運営費、６１ページ、生活保護費、６３ページ、清掃事務所職員給与費、同じく６３ページ、風しんについてお伺いします。５１ページの住民情報システムですが、このシステムは、そもそも区独自のシステムなのか、それともいろいろな自治体との連携がなされているシステムか、確認させてください。","respondent":"品川財政課長、山本情報推進課長、矢木生活福祉課長、工藤品川区清掃事務所長、鷹箸保健予防課長","answer":"特に木密対策等を積極的にやっているところであっても、なかなか当該の住民の方とかが応じないとか、そういった心理的なところもあって。こちらは、区で独自で開発しているものではございませんで、ベンダー企業が販売・提供しているものを契約して利用しているものです。生活保護の高齢単身世帯の現況と傾向ですが、現在、生活保護全体では４,８００世帯、５,６００人程度で安定的に推移していますが。","id":"exchange-149"},{"speaker":"石田（し）委員","kind":"質問","question":"生活保護費はわかりました。ただ、高齢者がなぜこんなに増えてきているのかというのは、区としてどのように考えを持っているのか、教えてください。風しんについてはわかりましたが、先ほど税務課長から、区民はどのような人たちが増えているという質問の答弁の中で、４０代、５０代の方が増えていますという答弁がありました。まさに風しんの制度に来年度から当たってくる世代です。","respondent":"山本情報推進課長、矢木生活福祉課長、鷹箸保健予防課長","answer":"委員おっしゃっていただいたスマホ一つで区のサービスが受けられる仕組みについては、まだまだ技術的には難しいところが多いかと思いますけれども。高齢者がなぜこのように増えてきているのかというご質問ですが、一定、人口の中でも高齢者というのが増えてきているのかなということと。委員にご指摘いただきました４０代、５０代に関しましては、先ほども話しましたが、私ども保健所がこれまで持っているツールでは。","id":"exchange-150"},{"speaker":"石田（し）委員","kind":"意見","question":"生活保護の高齢者の比率が高くなっている。僕は、これは国保も含めて、国民年金も含めて、年金が低いから生活保護のほうが、医療費も無料になって良いという声もなくはないのです。なので、それは区だけでなく、国の問題が多いのだとは思うのですけれども、区としてもその辺はしっかり見据えた政策をやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-151"},{"speaker":"南委員","kind":"質問","question":"５８ページの保育支援費について伺います。今年の４月に入園させたいと申請した人など、最終的な数字がわかったのではないかと思うので、質問したいと思います。申請数、内定数、不承諾通知数、そして、認可保育園を希望したけれども入れずに、認証保育園、企業立保育園、認可外保育園などに入った方々の人数、そして待機児数が何人かを伺います。","respondent":"佐藤保育課長","answer":"先日の第一回定例会でお伝えしました１次の申込者数は、全体でいうと昨年度から５件減です。ただ、２次のほうが若干増えておりまして、昨年度と比べるとトータルで５０件ほど申請数が、合算して増えているという状況です。","id":"exchange-152"},{"speaker":"南委員","kind":"質問・要望","question":"申請数ぐらいは発表していいのではないですか。内定数はいろいろなことがあるのかもしれないけれども、申請数ぐらい、そんな漠然としたことをおっしゃらずに、具体的な数字を言っていただきたいと思います。そして、待機児数は何人ぐらいになるのか、そのあたりもぜひ教えてください。質疑になりません。お願いします。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"１次、２次と分けて集計しておりまして、２次の有効申込者数は、ゼロ歳児が２５３名、１歳児が５５４名、２歳児が２０３名、３歳児が１２０名、４歳児が５９名、５歳児が４０名の状況で、内定の通知はこの週末に発送いたします。昨年４月と同様に、実質的な待機児童はゼロとなる見込みです。","id":"exchange-153"},{"speaker":"南委員","kind":"質問","question":"その数と比較しただけでも、倍以上増えていると認識をしていいのではないかと考えています。しかし、具体的な認証保育園とかに入った数は示されませんけれども、多くの皆さんは品川区の認可保育園に入りたいということで希望したわけです。そのことを品川区は、区民の皆さんの希望との関係で、これでいいのだと、これで我慢しろという認識でいらっしゃるのか、それについて伺いたいと思います。","respondent":"大澤保育支援課長","answer":"認可を希望されて認証に行く方というお話ですけれども、ゼロから２歳児でも、昨年の実績で辞退の方というのは３００人ほど出ていて、その方たちの辞退の理由というのが、それぞれいろいろありますけれども、認証のほうに決まったので。","id":"exchange-154"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、区民の要求に応えるべきだと思うのです。その点についての見解を伺います。そういう状況にもかかわらず、スペースがあるからいいとか、保育士を配置しているからいいということにはならないのではないですか。こういう実態についてどのように思っているのか、見解を伺いたいと思います。やはり解消するべきです。広いスペースで保育されるよう、環境改善を強く求めたいと思います。","respondent":"大澤保育支援課長、佐藤保育課長","answer":"かなりあきがある中で待機児童が生まれているというのは、もちろんマッチングという問題がありますけれども、それは、どうしてもこの園に入りたいとか、認証ではなくて認可に入りたいとか、いろいろそれぞれご事情がありますので。定員弾力化の関係ですが、先日もご答弁さしあげましたけれども、国の通知に基づいて、保育室の広さと保育士の数の確保をして適正に行うというところで、国がこういった通知を出している背景といいますのが。","id":"exchange-155"},{"speaker":"南委員","kind":"質問・要望","question":"そういう状況について、私はこれは大問題だと考えています。それから、待機児の問題ですけれども、やはりこれは父母の希望、要望を受けとめるべきだと思うのです。不公平ではないですか。大変な数字です。この削減額が補正予算のところに出ていますけれども、８億６,０００万円というふうに、開設しないで余った経費が出ているわけですけれども、これだけの金額がわかったのはいつごろなのですか。","respondent":"大澤保育支援課長","answer":"認可、認証を含めて、いつかは保育需要は減っていきますので、そのことを考えたときに、既存の施設の活用を前提に待機児童対策を進めていくのは、区として当然のことだと考えています。","id":"exchange-156"},{"speaker":"南委員","kind":"質問","question":"私は、１０月だったらまだまだ計画はできると思うのです。その点を指摘しておきたいと思います。この一般会計補正予算についての態度は、我が党は反対です。８６億円もの基金をため込む一方で、私どもが指摘をした、もう時間がないから具体的には言いませんけれども、今の待機児問題をはじめ、障害者問題、それから住宅耐震化、インフルエンザ等々、全く区民の要求に応えない状況ですから、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"こんの委員","kind":"質問","question":"私からは、５５ページ、サービス付高齢者住宅整備費助成、もう１点が６５ページ、下水道管改修事業、この２つをお聞きしたいと思います。こうした需要と供給というところでは、どのように捉えていらっしゃるのか、改めて区の見解をお聞きしたいのと同時に、毎年、今年度もそうですが、平成２８年度も平成２９年度も、この時期の補正で減額をされているのです。","respondent":"宮尾高齢者地域支援課長","answer":"３年連続で減額補正をしているということにつきましてですが、いかんせん相手があって、整備の事業者が、適切な場所に適切な規模で、適切な内容でのご提案があって、初めて整備するというものですので、私どもはＰＲ等を含め、最善は尽くしておりますが。","id":"exchange-158"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこら辺の何が課題で、何が適正ではないのかというところは、どんなことがあるのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"そうはいいましても、私どもとしては必要な政策ではあるという認識でおりますので、ご相談をいただいてから予算を計上するということになりますと、国とか東京都の補助金との兼ね合いもありますので、なかなか難しいということで、毎年当初予算で計上させていただいているです。","id":"exchange-159"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですが、その民間のサービス付高齢者住宅は、品川区の補助金は入っていない民間のサービス付高齢者住宅で、そこは区との連携はとれていないので、民間ですから利用料金が高い。そのために、区はとても手続が煩雑だという業者のお声も聞かれるところなのですけれども、民間の、区の補助金を少し入れた、利用者に使いやすいサービス付高齢者住宅に移行するという考え方はいかがなのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"確かにサービス付高齢者住宅というのは、大切な資源の一つということは認識しております。ただ、既存の住宅に公費を投入するということになりますと、何分、財政負担も多大なものになるということが想定されますので、そこにつきましては慎重な研究が必要かと考えています。","id":"exchange-160"},{"speaker":"こんの委員","kind":"質問・要望","question":"わかりました。慎重にこの辺を進めていくものとして、少し研究をしていただきたいと思いますが、いずれにしても、サービス付高齢者住宅は必要なところであるというご認識なので、できるだけ、毎年計上されている予算で、きちんと整備されるような流れをぜひつくっていただきたいと要望いたします。区の全小中学校の避難所、全て完了しているという理解でよろしいのでしょうか。現状をお知らせください。","respondent":"持田河川下水道課長","answer":"東京都からの受託ということで、我々の所管でも進めているところです。避難所ということで、最初は東京都で、先ほど委員からご質問ありました２,５００カ所というところで進めている、それは完了している。","id":"exchange-161"},{"speaker":"こんの委員","kind":"質問","question":"現状、ありがとうあります。上水道のこともちょっとお聞きしたいと思いますが、上水道管の直結工事も進んでいると思いますけれども、平成１９年から、大井第一小学校から進んで、平成２８年ごろまでにはほぼ完了という答弁も当初あったのですけれども、この状況はどうでしょうか。","respondent":"持田河川下水道課長","answer":"これも管の継ぎ手の部分を、上水道のほうはやっていると聞いてありますが、４０％という数字をいただいているところです。","id":"exchange-162"},{"speaker":"石田（秀）委員","kind":"質問","question":"最後になります。私からは、３４ページ、財政調整交付金についてお伺いをしたいと思います。６７億円増えたという補正であるのですが、この６７億円の評価というのは、どう考えられているのかというのを、まず伺いたいと思います。","respondent":"品川財政課長","answer":"これは多分、都の試算としても、かなり大きくずれたところがあるというところですが、これは、どうしても法人住民税の増加の分が、見込みよりもかなり多かったという点があるのかと予想はしています。","id":"exchange-163"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私はその分の活用という意味で言っているのではなくて、後で区長にも、もし見解があればお伺いはしたいけれども、５５対４５があって、その部分で、これがわかった段階で、２７６億円でもいいのだけれども、私の計算の仕方が間違っていればあれですが、７０７億円だと、それの２３分の１ぐらいが品川区かなと思っていたけれども、だから私は全体で１,５００億円ぐらいかなと思っていたのです。","respondent":"品川財政課長","answer":"それから見直し等も含めまして、かなりの項目で算定の部分はされてあります。ただ、そういった中でも、いろいろと財調につきましては課題がありますので、こういった部分につきましては２３区連携しまして、区長会等も通じて意見を出していくという方向で考えていくものです。","id":"exchange-164"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、ここがきちんと２０億円なり、そこら辺の５００億円を切ってどうということがしっかりないと、これは今度、区長会にかかってくるわけではないですか。は児相なり、４４項目なり、そういうものをもう１つ、事業はこういうこともやるから、それを組み込んでしまえというぐらいの話があってしかるべきだと思うので、そこら辺のお考えがあったら教えてください。","respondent":"濱野区長","answer":"そこでこの６７億円という額がどうなのかということだろうと思いますが、私は妥当というか、言い方が雑ですけれども、しっかり出した数字だろうと考えています。","id":"exchange-165"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/430016?Template=document&Id=1090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":127000,"voices":406}},{"id":"r01-20190305-3","meetingId":"r01-c-budget","date":"2019年3月5日","dateIso":"2019-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","topics":[{"id":"topic-01","title":"平成３１年度品川区一般会計予算","agenda":"平成３１年度品川区一般会計予算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"私からは、１４１ページ、歩行喫煙防止過料、１３８ページ、ふるさと納税寄附金、時間が余れば１６１ページの議会運営費について質問をします。これは昨年の決算特別委員会でも取り上げたテーマでありますが、予算書を見ると、過料の件数が、あくまでも予測でありますけれども、９６件となっています。昨年の決算では１８１件という数字であったと思いますので、半減していることになると思います。","respondent":"菅生活安全担当課長","answer":"平成３１年度の過料件数につきましては、これは平成３０年度４月から９月までの６カ月間の平均の過料件数が約８件ですので、その１２カ月分ということで９６件を計上しています。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"意見","question":"私はたばこを吸わないのですが、歩行喫煙の指導日数、指導している日は、どういったルートを決めていらっしゃるのか。例えば五反田地域をやるとなったときに、ここをこう回りましょうとかというルートを決めて指導していただいているのかをお聞かせください。","respondent":"菅生活安全担当課長","answer":"生活安全サポート隊は、路上喫煙禁止・地域美化推進地区５地区におきまして、それぞれ指導を行っているところです。指定喫煙所のある３カ所、大崎、大井町、五反田、この３カ所につきましては、指定喫煙所の見守りを兼ねまして巡回をしております。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"今のデータがあればで結構ですが、苦情がよくある地域は、例えば先ほどお話しした五反田駅のように、もともと喫煙所があったところが、私の体感としてかなり多いというふうに感じていますが、そこに関して特に区民からのお声はないのでしょうか。","respondent":"菅生活安全担当課長","answer":"平成２９年６月に五反田駅東口の喫煙所をＪＲの再開発ということで撤去いたしました。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"今のご答弁を考えると、この予算の過料の件数はちょっと少ないのかなというふうに思います。五反田地域だけではなくて、こういった苦情がある地域には、やはり需要があると思っていますので、その辺も踏まえて答弁をお願いします。","respondent":"菅生活安全担当課長","answer":"指定喫煙所の設置につきましては区として、分散をするという目的で、設置できる場所につきましては設置をしていきたいと考えています。やはりどうしても適地の場所、また受動喫煙の関係とかもございまして、そういった場所を今後も探しながら設置していきたいと考えております。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"ふるさと納税について伺います。これについては、以前から行政の皆さんにもかなり危機感を持って対応していただいていると思いますが、１６億円を超える流出ということで、流入に比べて驚異的な伸び率であると思っています。わかればで結構ですが、その原因というか、評価も教えてください。","respondent":"伊東税務課長","answer":"具体的に言いますと、昨年、平成２９年度では１１６万円ということでしたけれども、平成３０年度現在では３３０万円ほどと見込んでいるところです。こちらは、ふるさと納税ですので、税務課で扱っている分の金額です。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"区の返礼品の選定について、ご意見をお聞かせください。流出に関しても伺います。その中で品川区が２３区と比べて伸び率が大きいのか、額が大きいのかということもあわせてお聞かせください。それから、流出を抑えるために品川区ではどのような施策を行っているのか、これまで我が会派からも要望させていただいていると思いますが、その流出を抑えるための施策、現在行っているものがあれば教えてください。","respondent":"伊東税務課長","answer":"高額な返礼品ですけれども、なかなか先ほど例としてしながわ水族館等々ありましたけれども、返礼品として送るために調整が必要な部分もありますので、なかなか難しいかです。流出に関しましては、本区では１億ぐらいから毎年度伸び平成３０年度は１６億円ぐらいです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"５１ページの特別区たばこ税に関連いたしまして、受動喫煙対策について、６３ページ、区民活動交流施設使用料のこみゅにてぃぷらざ八潮について、１４７ページ、人孔蓋枠等工事費収入について、デザインマンホールについて、３点お伺いいたします。先ほど喫煙所の設置について質疑がありましたけれども、引き続きお伺いをします。特に、小中学校の学校の中ではどうなのかということもお聞きしたいと思います。","respondent":"伊崎地域活動課長、有馬庶務課長、川島健康課長","answer":"残りの２カ所につきましては、具体名を挙げますと、荏原第二地域センターは学校の隣接施設ということで、学校では屋外にも設置することはできませんので。学校につきましては、もう既に校舎内はもちろんのこと、敷地も含めて禁煙ということで対応しています。教育施設はそのような分類になりますので、今後のスケジュールでいきますと、７月１日までに法の基準に沿った形で。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"それぞれしっかりと行っていただきたいと思います。私のところに寄せられた声があります。具体的に対応されていることと思いますが、まず、ここは公園内に設置をされているという位置づけになっていると伺っておりますけれども、この場所の対応がどうなるのかお聞かせください。ぜひ通学に関しては、特に区から声かけをしていただいて、ご協力を願えるよう働きかけをお願いしたいと思います。","respondent":"溝口公園課長","answer":"これまでもその文化センターの利用者、地域センターの利用者、公園利用者、さまざまな方が利用してきた喫煙所になっておりますので、やはり今回、法改正または都条例改正の趣旨を踏まえて、望まない受動喫煙の防止、そういった対策は、今後。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"しっかりと対策をしていただきたいと思いますので、よろしくお願いいたします。続きまして、こみゅにてぃぷらざ八潮についてお伺いいたします。そして、フロアごとにそれぞれ所管が違うのですけれども、所管が違っても、同じ防犯対策がとられているのかどうかということを確認させていただきたいと思います。","respondent":"遠藤協働・国際担当課長","answer":"５時以降となると、なかなか費用がかかる部分がありますが、入居者の方にも、いろいろまた意見を聞き、利用状況、費用なども勘案しながら、この後も検討を進めたいと考えています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"２階の協働推進室を使われている方から、２階の防犯対策が手薄ではないかという声がありました。特にトイレの周辺、廊下のところも含めて、ぜひ確認を、委託であれば、委託業者に対応をしていただきますようにお願いをしていただきたいと思いますので、よろしくお願いいたします。次にちょっと違う視点で、こみゅにてぃぷらざの活用についてご要望がありました。","respondent":"宮尾高齢者地域支援課長、立川文化観光課長","answer":"ただ、もしよろしければ、今使っている高齢者クラブのほうに加入いただくということも引き続きご検討いただけたらというふうに考えているところではあります。そうしたことも含めまして、文化センターでのカラオケ利用のあり方については、今後、検討していく必要があるかと考えているところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"文化センターの位置づけというよりも、こみゅにてぃぷらざにおいてどうなのかということを、ぜひご検討をお願いしたいと思いますので、よろしくお願いします。ちょっと時間がなくなってしまったのですが、デザインマンホールについて、一言確認いたします。代表質問の中で、今後、５カ所にデザインマンホールが設置されるというご答弁がございました。この５カ所がどこなのかをお知らせください。","respondent":"多並道路課長","answer":"ただ、設置場所につきましては、東京都下水道局等と協議しながら進めますが、歩道上につけるということは交通安全上の観点で制約がありますので、我々の管理している中で見れば、駅前の歩道が場所としては有効ということで、駅前を中心に５カ所ということで、今後。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"１３８ページ、基金繰入金、１４０ページ、繰越金について伺います。繰越金とは何か伺います。あわせて、基金にはいろいろありますけれども、額が大きい主なものとして、公共施設整備基金、義務教育施設整備基金、財政調整基金、介護給付費等準備基金等がありますけれども、それぞれ区としておよそどれくらい積み立てるべきと考えているのか、区の考え方を伺います。","respondent":"品川財政課長","answer":"公共施設等整備基金につきましては、今後、施設の整備等に使っていくというような基金になっていきますので、そういった需要に応じて積み立てていく、そういうような考え方です。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"今回の予算では、公共施設整備基金繰入金に１２０億円、財政調整基金に約７億円、義務教育施設整備基金繰入金に１０３億円、基金全体で２４９億円を取り崩して歳入に充てています。伺いますけれども、各種基金を新年度予算の財源に充てるため、２５０億円取り崩してもなお、品川区が言う健全財政は維持されているという認識でよろしいのかどうか伺います。","respondent":"品川財政課長","answer":"当然、健全財政は、現在のところ維持しています。来年度、基金を２５０億円使うですけれども、これは年度年度によって、その年の財政需要があります。それにあわせて収入等を検討しまして、その中で基金をどれだけ崩してやっていくかです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"健全財政だということでした。維持というか、さらに積みます。例えば、予算特別委員会資料が事前に配られましたけれども、同じ昨年度の資料の各基金残高の年度推移では、平成３０年度末の基金は、約７０５億円余の見込みだったのです。７０５億円の見込みが９６９億円。なぜ最終的にこのように増えるのか、その理由を伺います。","respondent":"品川財政課長","answer":"当初の基金の崩しから年度末にかけていろいろ状況が変わってくるですけれども、これはやはり当初予算を設定した段階から、１年間の間に状況がいろいろ変わってくるものです。例えば、今年度に関しまして言えば、特別区住民税が納税義務者等の関係で大分予想よりも上がった。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"それにしても２６４億円も当初の見込みから増えることの説明がつかないように思えるのですけれども、私は今の理由では説明がつかないと思いますけれども、もう一度、それだけなのか、理由をお伺いします。","respondent":"品川財政課長","answer":"さまざまな事由によりまして、額が大きい小さいというところではないかというふうに考えております。いろいろな事由によりまして、額につきましては、その内容に応じて金額はいろいろ変化しているです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"平成２８年度では、当初１０３億円取り崩すと言ったけれども９３７億円に増える。伺いますけれども、区は基金の総額を少なく見せる、あるいは基金を取り崩して事業に充てているのだという姿勢をＰＲするために、このような出し入れをあえてしているのではないかと思わざるを得ません。そうでなければ、これほどまでのずれを毎年繰り返すということはあり得ないと思うのですけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"そういう中で歳入との見合いの中で基金を崩して予算を設定しております。年度末になりますと、さまざまな事象によりまして、その部分で金額を精算している、そういう形です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"私は、先ほど数字を紹介しましたけれども、２５０億円規模で当初の基金の見込みがずれるというのは、これはある意味、印象操作に当たるのではないかといいますか、そこまでずれるものですかと。毎年同じようなことを繰り返しているわけですから、逆に予算の立て方としてもどうなのかと。私は、こうした予算の立て方は、変更すべき、変えるべきなのではないかと思いますけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"毎年行政需要に応じて予算を立てています。必要な分は、全て予算のところで設定をしているという考え方です。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"国保料にいたっては、３０億円近くもこれまで一般財源から保険料の上昇を抑えるために投入してきたにもかかわらず、それをやめてしまう。一般財源に繰り入れてしまう。私は、そもそも当初予算のところからしっかりと区民生活の底上げのための予算を組まなくてはいけないのではないかと思いますけれども、区の考えを伺います。","respondent":"品川財政課長","answer":"議会から認められている予算です。そういった中で、区としては、しっかりと予算を組んで執行を行っているものというふうに考えております。ですので、予算の組み方がどうかということについては、すでにしっかりとやっているということでご答弁をします。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"予算をつくるのは行政の権限ではないですか。区民生活の向上のために使うべきではないでしょうか。伺いますが、例えば、特養ホームや障害者施設の増設、国保料値下げと子どもの保険料無料化、学校給食無償化、区役所・病院・買い物に便利なコミュニティバスの運行など、２３区で最低水準の福祉の改善にこそこの１,０００億円を使うよう求めますけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"予算は、さまざまな行政需要をもとに組んでいるものです。今年度につきましても、前年度の内容からいろいろなものを勘案しまして、今年度予算を立ててありますので、行政需要に対応した予算を今回も出しているというものです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ福祉を削減してため込まれたこの１,０００億円、この基金の一部をしっかり計画的に使って、暮らし、福祉第一の区政、そして２３区で最低水準の福祉を上位に底上げていくということを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"５０ページの先ほど来出ている特別区たばこ税に関して、歳出まで多少入ってしまうかもしれませんけれども、幅広くお伺いしていきたいと思います。それと、同じ５０ページの森林環境譲与税についてまず伺っていきたいと思います。私もときおりたばこ税について質問をするのですが、明らかにたばこ税は減収しているわけであります。それについて、所管はどうお考えなのか。","respondent":"伊東税務課長、品川財政課長","answer":"見込みとしては、この間も右肩下がりではありますけれども、今後もまだしばらく下がっていくような状況が続くと思います。こういう中で、本年度は、国から対象となる事業ということで、ある程度の項目がありまして、その中で区として合致するものを選定して、今回、予算のほうに上げているという状況です。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そういう喫煙所の確保も青天の喫煙所ではなく、しっかりとした屋根があって、しっかり隔離されたような喫煙所をつくるということが、やはりたばこを吸っている方は、大体、すごい税金を払っているのだという意識もあるわけですから、それは必要だと思いますので、各駅に対してもそうでありますし、行政のさまざまな施設もそうであります、特にシルバーセンターは、先ほど、新妻委員がおっしゃっていたように。","respondent":"伊東税務課長、小林環境課長","answer":"たばこ税の使途周知ですけれども、区の財政の公表というところでも出ておりますし、あと、たばこ商業協同組合で発行しております書類等にも、そういう形で載せて周知を図っているところです。東京都との連携ですが、引き続き、区が持っています要綱等を活用しながら、しっかりと普及啓発に努めてまいりたいと考えています。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"４８ページの特別区民税、５４ページの特別区交付金についてお伺いしますが、昨日の続きになってしまうのですけれども、国が都と特別区から吸い上げようとしているのですけれども、今は全体で増収だからいいと思うのですが、これから東京２０２０大会後に景気が悪化して減収になると、相当こたえると思うのです。","respondent":"柏原企画調整課長","answer":"そういったところがある中で、例えば、今ご指摘がありました東京２０２０大会の開催後の景気は、やはり注視しなくてはいけないということで、国民生活にも影響が出てくることがあるのではないかというところはありますので、平成３１年度。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"昨日も話しましたが、残業規制もかかるでしょう。もう１つ追加して、いわゆる外国の方が観光客ではなくて労働力という形で入ってきますね。ですから、企画部に政策という意味で伺いたいのですけれども、もう間近です。やはり区民にとって身近な行政として、企画部はどういうふうに考えているのかということを、しっかり今、押さえておかないといけないと思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"繰り返しになりますけれども、そういったものも含めて、先ほど申し上げました品川区長期基本計画の策定の中に分析も入れたいとは思ってありますので、政策という意味ですけれども、そういったところに対応できる政策を早い段階で検討を進めるべきだと思ってあります。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"特別区交付金ですけれども、昨日の補正から見て、改めてですけれども、随分控えめな数字だと思うのです。以前伺ったときに、堅めに見ているというお話があったと思うのですけれども、堅めに見るというのは、例えば９掛けするとか、９５％で見ると、そういう数字的なことは決まっているのでしょうか。改めて堅めに見る理由を教えてください。","respondent":"品川財政課長","answer":"今年度の特別区財政調整交付金の予算編成ですけれども、１２月末ぐらいに東京都からフレーム予算というような形で数字をいただいております。区の財調の予算査定は、基本的にはそれをベースとした形で算定をやっていくものになります。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"それと、東京２０２０大会期間中、交通ラッシュを避ける目的で、時差出勤とか言われているのですけれども、時差出勤となったときに、保育園はどういう形で対応していくのでしょうか。教えてください。","respondent":"辻オリンピック・パラリンピック準備課長、佐藤保育課長","answer":"時差出勤の話ですが、大会組織委員会等が東京都のほうで交通マネジメントということで、時差出勤等を促していこうということで、ただいま検討している最中でございまして、オリンピック・パラリンピック準備課は。時差出勤の関係ですけれども、保育園は７時半から夜の６時半までの１１時間が保育時間になっていますので、その範囲で対応できれば行いますし、延長保育に関しましては、今後、検討してまいります。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"品川・生活者ネットワークが求めたいことは、事業者の配分の仕方により、処遇改善が実感できていない保育士が出ないことであり、長く続けられるという補助金の目的を達成してほしいということです。１２月に報告された賃金改正は、全て東京都の補助金によるものなのでしょうか。全体の平均だけでなく、どういう役割の人にどのように配分されたのか、区は把握できているのかを伺いたいです。お答えください。","respondent":"大澤保育支援課長","answer":"主任保育士ですとか、副主任保育士ですとか、その役割ごとの平均値等も出しておりますので、区としては、全て把握しているというふうに認識しています。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"都の補助金が目的どおり有効に活用されたのであればよかったと思います。税金を投入した事業者で働く保育士の処遇改善が図られるよう誘導する責務が区にあると考えますが、いかがでしょうか。本当に保育士一人ひとりの処遇改善がされているのかを確認するために、例えば、抜き打ちのサンプル調査でもいいので、保育士に実施し、実態を調査してほしいと考えますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"加えまして、指導検査のときに、抜き打ちで給与台帳等を確認することもありますので、そういう意味では、賃金に関してはきちんと確認しているというふうに思っております。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"わかりました。本来の目的が達成され、保育の質の確保につながる労働環境が整うように求めまして、次にいきます。しながわ区民公園の屋外プールが２０１６年にリニューアルされました。２０１８年７月の区民委員会の中では、保健所との衛生問題や、国や都の動向を見るということでしたが、どのように検討されたのか、簡単にお知らせください。","respondent":"池田スポーツ推進課長","answer":"私どもとしましては、幼児の方が楽しめるファミリー用のプールということで平成２８年にオープンしていますので、昨年、区民委員会でお話があったことを受けまして、私どもでは、水着、水遊び用のパンツを履いてのプールでの遊びができないかどうかということで、今。","id":"exchange-029"},{"speaker":"田中委員","kind":"確認","question":"７月の区民委員会の答弁を受けた後に品川・生活者ネットワークで調査をしました。なぜ小さい子どもに対する入園禁止のルールが根拠もなくつくられてしまったのでしょうか。遅くともプール改築時にプールを設置する公園課、管理するスポーツ推進課、水質などのチェックをする生活衛生課の間で利用ルールや利用目的を再確認する協議の場を持つことをなかったのか伺います。","respondent":"池田スポーツ推進課長","answer":"プールの利用につきましては、従前からおむつをつけてのプールでの遊びはできないということでやってございましたので、プールを改築した際にも、それを引き継ぎまして、おむつ着用でのプールの入場はできませんということで運用しています。","id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"私が言ったのは、入園禁止について、国と区での公的根拠はなかった。この事態について、区はどのように受けとめるのか伺います。この事業に限らず、ほかの事業でも関係部署との連携をきちんととり、目的に反した間違った制度設計がされてしまわぬよう、お互いに目的やルールなどについて確認をとり合いながら事業を進めてほしいと思いますが、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"ご要望のしながわ区民公園の屋外プールの乳児の方の利用につきましても、昨年の区民委員会でご説明した以降、関係各課と詰めているところでございまして、実際に今年の夏、どのように利用できるかという話をしています。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"きちんと連携がとれていなかったので、今回このような質問をしています。それぞれの課にも確認しましたし、都などにも確認をしました。やっぱり問題としているのは、関係部署との連携が全くとれていなかったというところです。それらについてきちんと重く受けとめてほしいです。何かあれば一言ください。","respondent":"池田スポーツ推進課長","answer":"これからも各関係課との連携を進めて、区民の方のニーズに応えていきたいと思います。","id":"exchange-032"},{"speaker":"横山委員","kind":"提案","question":"１点目に、児童センター使用料、児童センター運営費についてお伺いいたします。そして２点目にまいります。昨年の決算特別委員会におきまして、新妻委員よりご提案がありましたが、ふるさと納税を活用したトイレトレーラーについて、発災時の各種トイレ確保の取組みの１つの可能性として前向きなご検討を進めていただきたいと考えていますが、区の検討状況をお聞かせいただきたいと思います。","respondent":"高山子ども育成課長、古巻防災課長","answer":"それから最後に、すまいるスクールの現在の状況という点ですと、地域のボランティアのご協力によって、特色ある活動が学校単位で行われているところではありますが、一例で申しますと。トイレトレーラーに関しましても、快適なトイレということで、非常に重要な部分がありますけれども、平時の利用に若干まだ課題があるのかというふうにも認識しておりますので、今後、研究課題とさせていただきたいと思います。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"ふるさと納税のガバメントクラウドファンディングの部分ですけれども、先ほど、我が会派の若手の芹澤委員の質問にもありましたけれども、品川区の流出抑制施策への評価について、１つお聞かせいただきたいと思います。見直し規定について、品川区はどのようにお考えなのでしょうか。条例の改正、条例のアップデートという点につきまして、品川区の現状と課題を教えていただけたらと思います。","respondent":"伊東税務課長、米田総務課長","answer":"条例の関係ですが、現在、地方税法といいますか、区の区税条例のほうで、このふるさと納税の控除の部分に対応しているわけですけれども、これから地方税法等の改正があれば、それに沿いまして、今。答えが合っていないかもしれませんけれども、区の条例のアップデート等の関係だと思いますけれども、こちらにつきましては、定例会でご議決いただいた後。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"ふるさと納税を活用しましたガバメントクラウドファンディングの手法を用いるということが、これから地域にチャレンジしたいと伺ったと思うのですけれども、今後、そういったものを広げていくに当たって、どの政策が、どういう方々の心に届いていくのか、分析の指標は居住地だけではないでしょうし、また、パーセンテージとか、数字だけであらわせるだけでもないかもしれませんけれども。","respondent":"柏原企画調整課長","answer":"そちらのほうも広域でやっていくという話も出ておりますので、そういったところを見ながら、また、独自でのやり方もいろいろな自治体で動き出しているというのは、こちらも把握しておりますので、ニーズ、何に使うということに関しては、よく検証しながら。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、１６１ページ、図書室運営費、７５ページのロケーション・写真撮影等、時間がありましたら、１４９ページ、広報しながわ広告料についてお伺いいたします。図書室運営費ですけれども、これは昨年度の予算も３７８万円ほどで、今年度も３７９万円程度と横ばいなのですけれども、この予算額の内訳を教えていただきたい。最近、利用しましたけれども、８年ぐらい前の本とかも置いてあります。","respondent":"久保田区議会事務局長","answer":"各種白書や法令辞書などは、充実に努めてありますけれども、古いものも必要なときもありますので、そういったものについては適時見直しを図りながら入れ替えているものです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。そうすると、やはり月刊誌とか、定期刊行物のコストがかなりかかっているということ。法令の追録もそうした特定の出版社の方が来られて、追録の差し替えとかをやるので、やはり費用がかかっているという理解でよろしいでしょうか。","respondent":"久保田区議会事務局長","answer":"法令追録は、やはり議会ですから、図書室に入っていただくとわかると思うのですけれども、かなりの法令がありますので、それを毎年追録しているということで、先ほども言いましたが、２６０万円ほどの経費がかかっているです。","id":"exchange-037"},{"speaker":"筒井委員","kind":"意見","question":"わかりました。そうした法令の追録や雑誌以外の新しい本は入ってすぐ左の端のほうにあると思うのですけれども、そういう本の選定をされている方は、どなたがやられているのかお知らせください。","respondent":"久保田区議会事務局長","answer":"本の選定は事務局で基本的に行ってあります。議会の審議や社会情勢等を見ながら、タイムリーな本を入れていくです。議員からリクエストがあれば、そういったものも入れているところです。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。調査研究に資する貴重な場ですから、引き続き、充実をよろしくお願いします。続きまして、ロケーション・写真撮影等についてお伺いいたします。昨年の予算は６８１万円ほどでしたけれども、今年度は７２４万円ほどと前年と比べて増えておりその原因は何か。それはフィルムコミッション事業やシティプロモーション関連の事業を推し進めていることに関係しているのかどうかをお聞かせください。","respondent":"今井土木管理課長","answer":"ロケーション・写真撮影等の経費ですけれども、平成２９年度は全体で２４５件、ロケーションと写真撮影の件数でございましたが、今、１月末現在ですけれども、３０３件ございました。やはり今、写真撮影などのご要望が多いということを土木管理課のほうで把握している状況です。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"その写真撮影が増えているというのは、やっぱり品川区のＰＲが効果として表れているということなのかということと、一番写真撮影の件数が多い人気の公園はどこなのでしょうか。","respondent":"今井土木管理課長","answer":"ロケーションと写真撮影については、文化観光課のロケーション事業と連携してやってございまして、中には免除になるものもあります。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうなのですか。公園は貴重な区有施設なので、こうした写真撮影やロケーションとかにどんどん使っていただいて、ひいてはそれが品川区のＰＲにつながるものと考えておりますので、今後とも品川区の公園を有効活用していただきたいと考えております。次に、１４９ページの広報しながわ広告料等ですけれども、広告主はどうやって募集されているのかお知らせください。","respondent":"中元広報広聴課長","answer":"広告主は、広報紙上での募集と、例年出される方がいらっしゃいますので、その方々にお声がけをする営業活動のようなものを続けているところです。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"広報しながわの紙面上で募集しているという意味なのかということと、例年出されている方は、私も大体同じところが出されているなと思うのですけれども、新規開拓はあまりお考えになっていないのでしょうか。","respondent":"中元広報広聴課長","answer":"広報紙の本来目的です記事を載せるスペースとの関係がありますので、スペースにもちろん余裕がございましたら、そういうところで募集の中で申込みがあればというところはありますけれども、現在のところ、実は埋まっている状況でございまして。","id":"exchange-042"},{"speaker":"筒井委員","kind":"意見","question":"今、新聞購読者が大分減ってきており、今年最新の情報を知ったのですけれども、８万３,７００部ぐらいに減ってきているということで、基本的に新聞折り込みで広報しながわはやられていると思うのですけれども、広告主は、そうした状況だと、広告を載せるのをしり込みしていくかと思っていますので、こうした新聞購読者の減による影響をどうお考えになりますか。","respondent":"中元広報広聴課長","answer":"広告主の状況ですが、実は決算ベースでは、毎年、増額傾向にあります。増えている状況ですので、広報しながわにおいて折り込む数の減少の影響は今のところ見られないところです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうなのですか。では、意外にあまり影響は出ていない。広報しながわからの貴重な広告料収入ですので、引き続き積極的に展開をしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"ご答弁では、５歳以上の全ての幼稚園児、児童、生徒ということで、東京都の設定に合わせているし、公私立保育園、認定こども園の子どもたちにも、５歳以上という照らし合わせる形での政策をということで確認させていただいて、東京都に対して引き続き強く要望していただくということになりましたけれども、改めてご答弁いただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京都では、大会組織委員会が用意している学校連携観戦プログラムの中で、東京都内の学校、幼稚園、小学校、中学校、特別支援学校、また義務教育学校を観戦プログラムの対象として、都の予算で、今、希望を募っているところです。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"私も２０１４年にクラウドファンディングの活用を品川区に求めてきて、こういう形で実施されるのはうれしいことなのですが、場合によっては、区民に対するクラウドファンディング的な手法を用いた財源確保というのも１つの方法としてありではないかというふうに思いますので、もう一度、何か意見があればいただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そうは言っても、最後まで現行の仕組みが変わらなかった場合にどうするかは、今後の課題ではありますが、必ずそれは施設によって子どもたちが観戦できないということがないような方法をとってまいります。","id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"それも含めて改めて確認させていただきたいのですが、まず、譲与税ということで、これは譲与税が５年間先に国のほうから用意をされ、各自治体に分配され、その使途、目的に基づいた形で各自治体がしっかりと取り組む。今申し上げたＳＤＧｓの観点ですとか、（仮称）しながわ環境未来館、そうしたところにこの譲与税が２０１９年度予算には計上されていませんが、活用できるかどうか、改めて教えてください。","respondent":"小林環境課長","answer":"森林環境譲与税の趣旨である地球温暖化にかかわる広域的な課題の１つとして森林の適正管理、それは必要なことだと考えています。そういった目的で、この税は、森林整備に必要な財源に充てるですので、そういった活用については、十分に活用できるものとして認識しているものです。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"これは、先にそういう財源が来て、実際には個人住民税の均等割に、平成３６年、今の復興財源が終わった後に課税されるという形になります。品川区としてどう見ているか教えてください。","respondent":"品川財政課長","answer":"概略を説明しますと、森林の面積が全体５０％分を占める形になっています。さらに、森林従業者、要するに、森林で働いている人たちの人数が全体の２０％となります。残る３０％は人口ということで、この部分で何とか品川区のほうにもお金が入ってくるというような状況です。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"そもそもこの税制を創設にあたっては、全国森林環境税創設促進連盟があり、そこに品川区も６２２市町村の中の１つとして加盟されていたかと思いますが、その加盟の経緯、また、その後の加盟したことによる品川区としての何かメリットですとか、そうしたところがあれば教えてください。","respondent":"小林環境課長","answer":"そういったような連携を深める事業を、引き続き検討を進めてまいりたいと考えています。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"この税制創設に当たって、そうした連盟に加盟していたというところでは、先ほど来の繰り返しになりますが、森林にかかわる、地球温暖化防止にかかわることについては、しっかりと実施していくという視点もしっかりと持ち続けていただいて、先ほど申し上げたＳＤＧｓの観点でありますとか、（仮称）しながわ環境未来館を建てるに際して、また、その後のさまざまな事業展開の中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、ページ１１９、衛生費補助金、地域自殺対策強化交付金から、品川区の自殺対策についてお伺いいたします。我が国は、先進国中で際立って自殺が多いことで知られており、厚労省が平成２９年にまとめた自殺対策白書では、Ｇ８中で自殺死亡率がロシアに次いで第２位でした。品川区の１０年間の自殺者数、１０年間の推移、性別・年齢別の自殺者の内訳について簡単にご説明をお願いいたします。","respondent":"鷹箸保健予防課長","answer":"自殺については、その１０倍ぐらいいると言われておりますので、本当に自殺というのは非常に重要な問題だと考えています。","id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"意見","question":"品川区も大体全国と同じような状況だということがわかりました。平成１８年に自殺対策基本法が議員立法で制定され、翌年、自殺総合対策大綱が打ち出されました。そして大綱では、平成２８年までに自殺死亡率を平成１７年の２０％以上減少させると数値目標も設定されました。１０年後の平成２８年、そのような取組みにより、この数値目標は達成され、自殺は減少しました。","respondent":"鷹箸保健予防課長","answer":"平成２０年から、今ご指摘がございました自殺対策連絡会をつくっておりまして、この目的は、自殺予防対策を具体的かつ継続的に実施し、さまざまな分野と連携を進めるためということで、警察をはじめ関係各所とともに、年に１回ではありますが、情報共有の機会を設けております。","id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"意見","question":"多くの年齢で自殺者が減少する中で、１９歳以下では依然自殺者の微増が続いており、早急な対策強化が必要とされています。特に１９歳以下の未成年層に対して、品川区の自殺対策について、特に何か加えることがありましたら、お願いします。","respondent":"鷹箸保健予防課長","answer":"区内の大学と連携をしまして、ハンカチ型のリーフレットなども作成して配布したところです。","id":"exchange-053"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"１９歳以下の自殺対策が非常に重要だと思われます。一般質問等でも繰り返し述べてきましたが、未成年者の自殺予防で最も必要なのは、自殺予防教育です。現に品川区でも子どもの自殺がありました。悩んだときに他者に援助を求めることの重要性を子どもに教えることが大切だと思います。品川区の自殺予防教育の現状と、今後の方向性についても含めてご説明をお願いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"今後とも命の大切さを子どもたちが自分で考え、自分の命、そして友達の命も大切にできるような子どもたちを育成してまいります。","id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"質問","question":"特に自殺予防に関しては、ゲートキーパー研修等で、大人の方、あるいは関係者、善意の第三者が支えるということで、研修等も繰り返されていますが、モチベーションというか、その話を聞いた後の感想を見てみると、あまり理解されていないで受けた方もいらっしゃるみたいなので、効果的な対処法に関して、最後に答弁をお願いします。","respondent":"鷹箸保健予防課長","answer":"ゲートキーパー研修も含め、自殺予防に関しては、ある人だけがやればいいということではなくて、関係各所、対応している全ての事業が自殺予防に役立つのではないか、自分が対応している人が自殺予防に必要なのではないかと考えながら事業を進めることが重要かと思います。","id":"exchange-055"},{"speaker":"おくの委員","kind":"質問","question":"１２５ページの第１４款都支出金、第２項都補助金の中の密集住宅市街地整備促進事業補助金、充当事業の木密地域不燃化１０年プロジェクトにかかわって、不燃化特区支援制度について伺います。品川区は、平成２５年から平成３２年にかけて、東京都の進める木密地域不燃化１０年プロジェクトに基づいて、不燃化特区支援制度を実施しています。そこでお伺いします。お伺いします。","respondent":"高梨木密整備推進課長","answer":"不燃化特区支援制度は、古い老朽化した木造住宅の取り壊しと除却、それに伴う住み替え、それと新しい住宅の建築にかかわる不燃構造化の支援ということで、３つの支援メニューで行っております。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問","question":"そこでお伺いします。品川区の耐震改修促進計画が改定されてからもう１年になりますけれども、不燃化特区内の耐震化率、それからそれ以外の地域の耐震化率、それぞれどうなったかおわかりになるのでしょうか。お伺いします。","respondent":"長尾建築課長","answer":"耐震改修促進計画の中では、不燃化特区と、それ以外の地域での耐震化率の統計は出しておりませんが、やはり不燃化の状況と耐震化の状況は相関も高いと考えますので、不燃化整備地域、不燃化特区のエリアは、耐震化率がほかのエリアに比べると低いと考えています。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"別の角度からお伺いします。不燃化特区支援制度で除却、建替えを支援しているわけですけれども、不燃化特区で一体何軒がこの制度を利用して建て替えになったのか。それから、別に耐震化支援制度があるわけですけれども、その制度を利用した除却などは、何軒やられたのか、それぞれお教えください。","respondent":"高梨木密整備推進課長、長尾建築課長","answer":"住み替え、建替えにつきましては、平成２８年度から支援を始めておりますので、今のご質問ですと、例えば、平成２９年度と今年度の見込み数で言いますと、除却は２４７棟を見込んでおります。耐震事業における除却の件数ですけれども、こちらの事業は平成２３年度からスタートいたしまして、平成２９年度、平成３０年度の除却実績で申しますと、平成２９年度が１７０件、今年度につきましては、２月末時点ですけれども。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"もう１つお伺いします。不燃化特区というのは限られた地域なのですけれども、不燃化特区の広さ、面積は、品川区全体の何％ぐらいなのでしょうか。","respondent":"高梨木密整備推進課長","answer":"不燃化特区は、全９地区で２８５.５ヘクタールあります。これは区全域の割合で申しますと、１２.５％、約８分の１です。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問","question":"もう１つの、それ以外の耐震化支援制度のほうは、もっと広い地域で行われているわけです。除却に関しては品川区のかなり広い地域で行われていますね。それは耐震化に向けて同じくらいの件数の除却がされているということがわかると思います。平成３２年までの限定した期間の制度とされていますけれども、もう少し長くやるべき制度ではないかと思いますけれども、その点、いかがでしょうか。お伺いします。","respondent":"高梨木密整備推進課長","answer":"ただ、改善が必要なさらに広い整備地域、木密地域と呼ばれる整備地域におきましても、耐震化の除却ということでしっかりと支援をしていく、しっかりとランクを分けて助成をしていくことで、安心安全のまちづくりに努めたいという方向性で進めているところです。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"さらにもう１点、品川区耐震改修促進計画の最後にアンケートが収録されています。耐震改修を実施しない理由を区民の皆さんに伺っているのですけれども、その中の５０％の方が、耐震改修に要する費用負担が大きいことを実施しない理由に挙げていらっしゃいます。その点からも、この不燃化特区支援制度を拡大することを強く求めて終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"木村委員","kind":"質問","question":"最初に議会費ですけれども、平成３０年度、約８億７,０００万円、平成３１年度は約８億５,７８０万円ですけれども、この差額が大体１,２００万円ほど減額をされていますけれども、どの分がカットされたのでしょうか。そして、議場を手直しをするということもお聞きいたしまして、どこをどのようにし、また、何のために行ったのでしょうか。","respondent":"久保田区議会事務局長","answer":"それと、本会議場のバリアフリー化につきましては、本会議場の演壇のところを車椅子の方でも一般質問ができるようにということで、まずはそこをフラットにして、また、演壇を電動で上下できるものに変更したというものと、本会議場の中に手すりをつけたです。","id":"exchange-062"},{"speaker":"木村委員","kind":"質問・要望","question":"ありがとうございました。そして、運営費のところですけれども、聴覚障害者傍聴対応システム導入、５９万４,０００円が計上されていますけれども、聴覚障害者対応とは、本来であれば、傍聴席に向かって行う手話のことだと思っていました。そうでなければ、映像や文字対応となるのでしょうか。手話でなければ、そういうふうな映像や文字対応になるのでしょうか。お聞かせいただきたいと思います。","respondent":"久保田区議会事務局長","answer":"聴覚障害者傍聴対応システムですが、こちらは聴覚障害の方に対して、一般質問やその答弁に係る部分を音声を文字にして傍聴をしていただくというシステムを導入するものです。","id":"exchange-063"},{"speaker":"木村委員","kind":"質問","question":"これは例えばの話ですけれども、聴覚障害者の方が町を歩いているときに緊急の場合、１１０番や１１９番などをしなければならないようなときに、タブレット端末から電子メールを利用し通報を行うことによって、救急車や消防車の要請ができるようですけれども、この聴覚障害者傍聴対応システムは、今言った逆の仕組みであると考えてよろしいのでしょうか。タブレットを使うということでよろしいかどうか。","respondent":"久保田区議会事務局長","answer":"それを本会議場の中で通信をしまして、タブレットに文字として表示をするというシステムを考えています。そのタブレットを傍聴の際に申し出があれば貸し出しをしまして、それによって一般質問やその答弁などを文字で傍聴していただくというシステムを考えているところです。","id":"exchange-064"},{"speaker":"木村委員","kind":"質問","question":"２月の新聞に、川崎市議会で議員や理事者の発言を瞬時に文字化していく、そして傍聴席にあるモニターに表示をする仕組みが入ったそうですけれども、これは聴覚障害者だけではなくて、高齢者をも対象にした試みだという紹介をされておりました。これを採用するということでよろしいのでしょうか。もう一度伺います。","respondent":"久保田区議会事務局長","answer":"ただ、機種というか、システムの会社によっていろいろな種類がありますので、どれを採用するかはこれからになりますが、基本的な部分といたしましては、同じというふうに考えているところです。","id":"exchange-065"},{"speaker":"木村委員","kind":"質問","question":"モニターに映し出すということをお聞きいたしました。市が使っている独自用語というのでしょうか、そういう言葉や、また、議員の氏名などはあらかじめシステムに登録をしておくということをお聞きいたしました。そして、ＡＩの性能がいまいちということをお聞きいたしましたけれども、本区ではＡＩは使わないということでよろしいでしょうか。","respondent":"久保田区議会事務局長","answer":"１点目の運営の経費ですけれども、予算書にありますように、品川区議会では、５９万４,０００円を予定しているものです。","id":"exchange-066"},{"speaker":"木村委員","kind":"意見","question":"もう１つ、福井県議会ですけれども、２０１７年６月から、このようにして、議員の発言を傍聴席のモニターにリアルタイムで文字化するのですけれども、そこではＡＩは使わずに、専門の委託業者が音声を聞きながら文字変換をしてモニターに映し出すというふうなやり方をしているそうです。そういうものを残すというようなお考えはあるのかお聞かせください。","respondent":"久保田区議会事務局長","answer":"手話についてですが、現在、本会議をケーブルテレビやインターネットで中継する際には、手話通訳を入れて放映をしているところでありまして、それについては引き続きそのような形で対応していきたいと考えています。","id":"exchange-067"},{"speaker":"木村委員","kind":"意見","question":"この計画は以前からあったのだと思いますけれども、今がジャストタイミングと捉えての予算計上なのかどうか。そして、この計画はいつぐらいから考えられていたものでありますか。","respondent":"久保田区議会事務局長","answer":"平成２７年度からも議会改革検討会で議場のバリアフリー化ということでご議論をしていただいてきたところの中の１つで、今回の聴覚障害者傍聴対応システムの導入につきましては、昨年度の議会運営委員会の中で議場のバリアフリー化の１つとして提案をされたものでございまして。","id":"exchange-068"},{"speaker":"木村委員","kind":"意見","question":"開かれた議会としていろいろと考えますけれども、議会が開催されている模様を今、傍聴に来ている人だけではなくて、役所にいろいろな手続をしに来られている方々や通行人の方々、そういう方々にもっともっと見ていただくために、これは丸きり素人考えなのですけれども、３階の大きいエントランスといいますか、広いところがありますけれども、そういうところの壁に大きなビジョンをつけて。","respondent":"久保田区議会事務局長","answer":"そうした意味で、いろいろ幅広く傍聴ができるような環境整備は着実に進めているところです。","id":"exchange-069"},{"speaker":"渡辺委員","kind":"質問","question":"１１５ページ、高齢者クラブ支援事業、１２７ページ、空き家の利活用、この２点で伺わせてもらいます。高齢者のほうからです。名称のことで伺いたいのですが、高齢者クラブの現状の課題として、加入が伸び悩んでいるやに聞きます。そこで、ネーミングの話が１つ地域課題として聞いています。このネーミングの工夫が区の裁量でどれだけできるのかはありますが、まずネーミングに対してお考えを教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"高齢者クラブに関するお尋ねを２点ほどいただいたかと思います。１点目のネーミングについてですが、確かに私どものほうにも、新しい名前を考えてみてもいいのではないかといったお声をお寄せいただくことがあることは事実です。","id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問","question":"この中で、では、品川の今の施策のいいところは、「チャレンジ」というキーワードで、ぜひとも取組んでもらいたいという思いで伺っていきます。では、それをどう支えていくかという点では、ここは加入促進をミッションとして、外部委託といいますか、コンサルも含めて、専門家の力をここは１回借りてもいいのではないかという思いです。この辺のストーリーを所管としてどう考えているか教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"委員からご提案いただきましたアンケート調査を含む大規模なもの、例えば外部の力を借りた調査、アンケートにつきましては、また連合会の役員の皆様とも相談をさせていただきながら検討してまいりたいと思っているところです。","id":"exchange-071"},{"speaker":"渡辺委員","kind":"質問","question":"ただ、今、軸である役員の方々、地域の方の負担を減らしていく、その意味で行政がすべきこと、あるいは事業者の活用という意味で聞きましたのご検討ください。続きまして、空き家の利活用を伺いたいと思います。それとあと、第１回目の調査のときですか、品川区全体の空き家の状況、この辺が最新の情報だと、どのような形なのか。この辺の区分の特徴を、まず最新のものとして教えてください。","respondent":"森住宅課長","answer":"今年度も実施をしておりまして、その中では合計１２件が空き家について何かしらの情報提供を欲しいというふうに言われているところです。","id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問","question":"やはり次年度拡充すべき事業なのかという裏づけにもなるのではないでしょうか。あるいは、私ら素人だと、戸建ては見た目でわかる、でも、どういうカウントになっているかわからないですが、やはり集合住宅は今、品川区も６割を超えるぐらいかと思われます。増えるといいますか、そういう中では継続した調査といいますか、どのように考えられているのか教えてください。","respondent":"森住宅課長","answer":"ほとんどが空き室というふうに国の調査ではなっておりますので、そういった部分も含めて、あるいはマンションのこれからの適正管理という部分を含めて対応していかなければいけないものかと考えております。","id":"exchange-073"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それぞれの最新情報をありがとうございました。特に集合住宅、マンション等も、今聞いて、なるほどと。ますますこれはニーズが高くなっていくと思います。昨日も公明党の塚本委員から国のほうでの除票の保存期間延長に関する質疑があったかと思います。これはすぐではないにせよ、空き家からの関連で、やはりプロジェクトチームが必要かと思いますが、その辺のお考えを最後に伺って終わります。","respondent":"森住宅課長","answer":"士業の力も借りてというお話がございました。空き家の情報公開サイトもやっておりますので、その中でいろいろ連携してまいりたいと思います。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"非常にネーミングがいい響きだなと思うのですが、会派といたしましても、２０１７年から、子ども食堂を補完し、子ども食堂に行けないようなさまざまな事情を持ったご家庭に、アウトリーチしていくための、ひとり親世帯や低所得のお子さんたちに、そういうお子さんたちがいる世帯、困難を抱えた世帯に対して、直接食料品等を送付するような事業をずっと求めてきたのですけれども、ここに来て。","respondent":"廣田子ども家庭支援課長、品川財政課長","answer":"ですので、ひとり親の現況届等にて６月から８月に周知を行い、準備が整い次第スタートということで考えてあります。申し込みについては、品川区社会福祉協議会等と協力して品川ボランティアセンターを使ってやる予定でおります。ガバメントクラウドファンディングですが、ふるさと納税のサイトを利用しまして、基本的にふるさと納税は各自治体で、自治体に寄附をして商品をもらうというような仕組みになっていますが、最近はふるさと納税のサイトの中で。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは毎年やらせていただいていますが、トイレの洋式化について確認をさせていただきたいと思います。２年前ですけれども、その間もいろいろ質疑もあったのですが、２年前の平成２９年度の予算特別委員会の中の総括質問の中で確認をさせていただいたときには、学校トイレの総数が２,３５７で、洋式化率が６３.４％、２３区の中でも、東京都の中でも非常に高い数字でした。","respondent":"有馬庶務課長","answer":"そのうち洋式のトイレが２,０７８ということで、７０.８％となっているものです。平成３１年度につきましても、小学校５校、中学校１校で洋式化を進める予定でございまして、これが全て終了しますと、洋式化は７５.０％に達する見込みです。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問・要望","question":"来年度末までいけば７５％に達するということで、非常に進んでいるのかです。以前の質問において文部科学省からのトイレの状況調査に対する教育委員会のご回答をもとに質問させていただいて、教育次長からは９０％以上、洋式化するというご回答をいただいております。今後も目標の達成に向かって着実かつ迅速に学校トイレの洋式化を進めていただきたいと思いますが、最後に確認をさせてください。","respondent":"有馬庶務課長","answer":"トイレの洋式化につきましては、先日も役員・校長会で意見交換をさせていただきました。基本的には、洋式化の流れを推進していくほうがいいだろうという意見が出ましたので、９０％というのは一定の目安として置いておきながら進めていきたいと考えています。","id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは、本当にとんでもない話であって、絶対にあってはならない話なのですが、品川区の教育委員会ではないとは信じますけれども、品川区の教育委員会、これは虐待事案、いじめの項目で虐待の話もあれなのですが、いじめと虐待に対応するスクールロイヤーということで、品川区の教育委員会が、今、司法、特に弁護士とのご関係について、どのような関係性を保っておられるのかお伺いしたいと思います。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"現在、教育委員会では、教育訟務員という形で教育委員会の非常勤職員という位置づけで弁護士資格を有している方を任用しています。人数は１名です。その弁護士とは別に、品川区いじめ対策委員会では、弁護士に委員として入っていただきまして、学期に１回程度、さまざまな学校問題、特にいじめ対策を中心とした取組み等についてご報告申し上げる中でアドバイスをいただいています。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"確認","question":"教育訟務員として１名、そしていじめ対策委員会に１名ということで、２名の方が関与をされていらっしゃる。先日も文教委員会で報告がありましたけれども、いじめの訴訟の和解の中で、対応された弁護士というのは、そちらの弁護士でよろしかったどうか確認をさせてください。それともう１つ、続けて質問してしまいますけれども、そのお二人の役割を教えてください。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"教育訟務員の役割ですけれども、職務内容といたしましては、教育行政に関する法律相談および品川区教育委員会に関する訴訟事件の調査です。過日ありましたいじめ裁判にかかわっては、こちらの教育訟務員に携わっていただいたところです。いじめ対策委員会には、学識経験者として、弁護士のほか、福祉、心理、学校教育に関する学識経験者に委員を委嘱させていただいておりまして、いじめ対策委員会の弁護士は、重大事案が万が一起こってしまった場合には。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２３区では来年度を含めれば２区が始めるというところがあります。こういったことに対して、本区の教育委員会が、いますぐこれを取り入れるというのは、まだまだ早いのかなと、早いということもないのかもしれませんが、まだまだこれから研究していくことなのかと思うのですけれども、このあたりについての認識、司法の教育への関与について、ご見解を伺いたいと思います。","respondent":"有馬庶務課長","answer":"現状は、学校から直接すぐ相談に行っているという例は少ないのではないかと感じております。今後は、ブロック別にするとか、そういったところは他区のことも見ながらということになりますけれども、現状は、１名の中での運用を考えていきたいと考えています。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"今回、国から社会資本整備総合交付金として約３,２７０万円、都から都市計画交付金として８１０万円、補助金として見ると、区からも出ますので、合計すると約６,５４０万円が戸越公園駅前の五丁目１９番地区に投入されるということになりますけれども、今回のこの補助金、前回から約２倍弱に増えていますけれども、この理由を伺います。","respondent":"東野まちづくり立体化担当課長","answer":"戸越五丁目１９番地区再開発事業に係る補助金についてのお問い合わせです。こちらは平成３１年度の補助金につきましては、現在進められております再開発計画のうち、権利変換計画の作成費、それから建築設計費に当たる部分です。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のご説明は、設計費の部分の補助金が増えたということで、約２倍に増えたということでよろしいでしょうか。それを確認させていただきたいと思います。この計画には、総事業費１４６億円のうち、補助金等は約３２億円、総事業費の２２％にもなります。これまでは１つの計画当たり約２割程度だったかと思いますけれども、補助率が２割を超えた理由を伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの再開発事業の補助金に当たる部分につきましては、事業計画作成費のほか、建物の共同施設整備に係る費用等々にかかるものでございまして、補助対象事業費をあらかじめ算出しています。こちらの約３分の２に当たる部分が補助金の支出となります。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"なぜ補助率が２割を超えたかをお聞きしました。これまでは１０何％とか２割弱ぐらいだったと思うのですけれども、この計画で２割を超えた理由をお聞きしたいので、ご答弁をお願いいたします。","respondent":"東野まちづくり立体化担当課長","answer":"再開発事業につきましては、その再開発事業の規模等によりまして補助金の総事業費に係る率が変わってくるものということになります。こちら、戸越五丁目１９番地区の再開発事業につきましては、こちらの補助金については適正に算出しているものです。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問","question":"規模に応じ全体の率が変わるということでしたので、今回の戸越五丁目１９番地区というのは、敷地面積が０.３ヘクタールで、非常に小さいものになりますけれども、規模が小さくなると補助率が上がるということでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"敷地面積に占める割合という部分も一定程度関係してくるかと思います。敷地面積に占める部分のいわゆる公共施設という部分の割合については、やはり敷地が狭くなる部分については、その部分が高くなるというようなことが傾向としてはあるかと思われます。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。この戸越公園駅前に２３階建て、８５ｍの超高層は駅周辺の町にふさわしいと思いますかという質問に、ふさわしくないという方が７１％答えています。こうした区民の声を区はどのように受けとめているのでしょうか。私は、超高層再開発はやめるべきだと思いますが、いかがでしょうか。区は、この計画が町に調和してふさわしいと思っているのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"ただ、それについては今後の町の全体の計画の中で皆様のご意見を聞きながらつくっていくものだと私どもは考えているところです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"アンケートに寄せられた声を紹介いたしますけれども、長い時間をかけて作られたこの土地に合った町並みや商店街から、どこへ行っても同じような感じになり、本当にもったいないと思います。そういったときに、ぜひ区のほうで計画を変更していく、ふさわしくなるようにしていく必要があると思いますけれども、私はこの超高層再開発は税金投入をやめていくべきだと思いますけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"先ほどもお話しさせていただきました権利者みずからこの町に必要だという基盤整備をもとに、この再開発を計画しているものです。このまちづくりにおける調和という部分につきましては、景観形成といったものも含めまして、区も指導していきたいと考えています。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"昨年の第４回定例会では、再開発で住民がばらばらになってしまうのに、なぜ絆が深まるのかという質問に、お互いの理解を深めるということで、そういったことが進むという答弁がありました。そもそも借家やお店を借りている方は、賃料が上がるなど、残ることはできません。地権者が残れるよう話しているということですけれども、現在の状況と、借家人についてはどうなっているのか、本当に残れるのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"借家人、賃貸借人のところですけれども、再開発組合が借家人、賃貸借人につきましても、再開発事業を進めるに当たっては説明会を行ってありますので、区としては、その推移を見守ってまいりたいと思います。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"借家人については説明会を行うということでしたが、つまりは、残れるのか残れないのか、私は残れないと思いますけれども、伺いたいと思います。部屋を実際に借りている方からもお話を伺いましたけれども、引っ越し先を探しているということで、品川区では難しく他自治体で探しているということでした。結局、住民はばらばらになって絆を深めるどころではないと思いますけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"借家人が残れるか残れないかという部分ですけれども、今後、オーナーとの話し合いになってくるかと思います。一定の賃料は今までもかかっているものですので、今後、再開発ビルに入居する方につきましては、一定の賃料が今後もかかってくるものだと考えています。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"賃料がかかるのは当然だと思いますが、結局は残れないと思います。それから駐輪場についても伺ってまいります。戸越公園駅周辺では、今お話ししてきました１９番地のところですとか、ほかのところでも再開発などが進められようとしておりますけれども、戸越公園駅の現在の駐輪場利用状況、３年程度の増減の傾向などを伺います。","respondent":"古郡交通安全担当課長","answer":"戸越公園駅第２については、平成２７年が３２.１％、平成２８年が２６.５％、平成２９年は４４.１％ということで、本年度については５１.７％で、おおむね５０％程度で推移しています。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"そのため障害者の方ですとか、お年寄りなどは、危険な状況に置かれているのではないかと思いますけれども、この状況が危険だと思っているのか、改善していくべきだと思いますけれども、そういった中で、この自転車の駐輪の使用料は、今、１日１５０円ということになっておりますが、これを短時間の利用は無料にして、また利用料も下げていくことで、放置自転車の解消にもつながってくると思いますけれども。","respondent":"古郡交通安全担当課長","answer":"危険な状況につきましては、区では放置禁止の指定区域がありますので、撤去活動を実施していきたいと考えております。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"近隣の自治体でも、一定時間の無料は導入されております。港区では２時間無料、目黒区では１時間無料、大田区では無料制のところもありますので、品川区でできないことはないということで、その考えを改めていただいて、短時間利用ができるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"大沢委員","kind":"質問・要望","question":"１５５ページの歩行者用観光案内標識設置支援助成金、それと４８ページの特別区民税、これは税金のことではなくて、人口流入について伺いたいと思います。１５５ページですけれども、ピクトグラムについてのお話を伺いたいと思います。","respondent":"中元広報広聴課長","answer":"品川区では、国や東京都から出されます指針に応じまして、区としての指針、マニュアル等を改定していくということで対応しています。","id":"exchange-092"},{"speaker":"大沢委員","kind":"質問","question":"２０２０年に向けた対応を既にされているという認識でよろしいでしょうか。","respondent":"中元広報広聴課長","answer":"東京都のほうで２０２０年に向けた対応をなされたものが公式に出ましたら、それに応じて対応しています。平成２９年度のところで一度対応をしています。今後また出てまいりましたら、それに応じて早急に対応してまいりたいと考えています。","id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"ここのところでピクトグラムの位置づけについて伺いたいと思いますけれども、今、そのような区の取組み、英語でコミュニケーションを交わすことができるようにする取組みが行われておりますけれども、先ほど、課長がおっしゃったように、都からの依頼に基づいて、ピクトグラムを掲示をしていくのか、あるいは、区民の英語力の向上のために、あえてそこのところを必要最小限にしていくのか。","respondent":"中元広報広聴課長","answer":"どちらかと申し上げますと、やはり品川区だけのことではございませんので、やはり都内全体並びに全国的にも統一的なものが必要かと思ってありますので、やはり英語の向上というところもあるかもしれませんが、区といたしましては。","id":"exchange-094"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、ピクトグラムと英語力の向上に向けて、２つの取組みを同時進行で行っていく、このような考えでよろしいですかね。","respondent":"中元広報広聴課長","answer":"現在も既に町の各課で所管しておりますサインの表示につきましては、英語表記等も併記していますので、各課、２０２０年に向けて計画的に始めているところですので、今後ともその中で行ってまいりたいです。","id":"exchange-095"},{"speaker":"大沢委員","kind":"質問","question":"あまりピクトグラム自体が親切過ぎてしまうと、かえって英語力の向上に水を差すのではないかというふうに私は感じるのですけれども、そこはどういうふうにお考えになりますでしょうか。","respondent":"中元広報広聴課長","answer":"ピクトグラムが表示されているのは、本当に街区表示板ですとか、一部のものですので、それだけで区民の方の英語力の向上を妨げるものになるとは考えていないところです。","id":"exchange-096"},{"speaker":"大沢委員","kind":"提案","question":"決して勉強のツールではないのですけれども、意外と言語というのは困って初めて身につくものだと思いまして、私は、提案を投げかけているわけであります。要は、ピクトグラムが間近にあって、外国の方が聞く、聞かれて困って自分の少ないながらも語彙力でその人に説明をする。次へいきます。区民税が増えているということですから、これは人口が流入しています。","respondent":"柏原企画調整課長","answer":"いろいろな地方、関係の都市等ありますので、そういった状況を見ながら、検討の１つであろうというふうには思ってあります。","id":"exchange-097"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、７７ページ、１２款１目の情報公開手数料、１１１ページ、１４款、障害者施策推進包括補助金、１２０ページ、同じく１４款５目、土木費補助金について伺います。最初に、情報公開手数料です。だったら、どのようにして審議会での審議に至るかが明記されていないこのホームページ上の記載はとても残念で、不十分と考えますが、ホームページ上の掲載について見解をあわせて伺います。","respondent":"中元広報広聴課長","answer":"２点目のホームページへの記載ですが、現在、審査請求の流れというものを紙ベースでつくり、職員にも職員ポータルの電子掲示板等で周知したものと同じようなものを、そちらにも掲載をするということでやらせていただいております。","id":"exchange-098"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、チャートみたいなものが出ているのですけれども、審議会に至るまでと書いてありましたか。審議会に至るというところまで、ぜひそこまでを書いていただきたいのですが、その点について再度お願いします。","respondent":"中元広報広聴課長","answer":"近々に出していますが、審査請求書の提出に始まりまして、弁明書の提出、反論書の提出、審議会への諮問、審議会からの答申、採決というところまでをチャートにさせていただきました。それを掲載させていただいてあります。","id":"exchange-099"},{"speaker":"吉田委員","kind":"質問・要望","question":"これについては確認させていただきました。皆さんにちゃんと知らせていただきたいというふうに思います。次に、情報公開の件数の数え方について伺います。事故報告書については、その後、改善していただいているので、話を蒸し返すようで申しわけないのですけれども、改善前であっても、この考え方でいったら、件数としては１件ではないのかというふうに思うのですが、その点について見解を伺います。","respondent":"中元広報広聴課長","answer":"その資料をつくったときに、１度決定をとっているので、それで先ほど事例に出されたものとは別々ですという判断をされたのではないかと考えているところです。","id":"exchange-100"},{"speaker":"吉田委員","kind":"質問・要望","question":"数え方について、本当にこれだと解釈が分かれるかなという表記です。そういうことがないように、ぜひ統一した見解を持っていただきたいと思います。それから、障害者施策推進包括補助金から伺います。今までレスパイト事業について何回か質問させていただきましたが、ピッコロで行われているレスパイト事業と、在宅レスパイト事業、両方について、現在の利用状況を教えてください。","respondent":"松山障害者福祉課長","answer":"在宅レスパイト事業についてですけれども、こちらは訪問型が伸びている状況にあります。訪問看護ステーションからの訪問型が非常に需要が高く、やはりそちらの伸びが多うあります。","id":"exchange-101"},{"speaker":"吉田委員","kind":"質問","question":"それで、もう１つの介護士の派遣型がなかなか伸びないということだったのですが、前に伺ったときに、在宅レスパイト事業について、使いたいのだけれども、どこにも通っていないことが条件だと言われて使えなかったという当事者のお声を紹介しました。要綱にないような規制はすべきではないと考えるのですが、その点について見解を伺います。","respondent":"松山障害者福祉課長","answer":"確かに要綱の文言からは非常に読みとりにくいということがありますので、運用上の課題として、障害者福祉課では捉えております。お困りの方がいらっしゃらないような形で運用を図っていきたいと考えていますので、今後、整理いたしまして、検討してまいりたいと考えています。","id":"exchange-102"},{"speaker":"吉田委員","kind":"確認","question":"時間がないので確認だけさせてください。区市町村居住支援協議会活動支援補助金についてです。昨年の予算特別委員会で、福祉部の視点では、これの取組みが難しそうだったので、土木費の住環境改善促進施策の一環として視点を持ち得ないのかと質問をしました。このたび、住宅課として支援をしていくということで理解してよろしいでしょうか。","respondent":"森住宅課長","answer":"来年度から具体的に住宅確保要配慮者に対して、利用機会を充実して支援を続けてまいりたいと考えています。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"５４ページの歳入、特別区財政調整交付金についてお伺いいたします。さまざまなことが話し合われて、２月２０日に２０１９年都区財政調整協議会の議事録が特別区長会ホームページで公開されました。この財政調整協議の中で、児童相談所関連経費については、この協議会で協議されたと思いますが、区側の主張と、それに対する東京都側の主張について、ご説明いただきたいと思います。","respondent":"品川財政課長","answer":"基本的に区側としましては、財政調整需要額のほうに算定した上で、移管される事務の規模に応じた配分割合の変更を要望しておりましたが、都側は、やはり一部の区が自主的な意向に基づき進めている点とか、特別区が等しく行うべき事務は慎重に検討される必要があると。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問","question":"私は、今お話があったように、区側の主張は当然正当で整合性があるというふうに思っております。このような状況の中、このお話を伺うと、東京都は頑なに拒んでいるかのような印象を受けるのですが、今後、区長会としては、どのような対応をしていくのでしょうか。平成３２年には３区が開設する予定になっているということは、平成３１年度中に平成３２年度の話も出てくるかと思いますが、お伺いします。","respondent":"品川財政課長","answer":"今後のことですが、来年度の財調の交渉につきましては、同様に配分率の変更について、それから、算定される部分の計上部分について検討していく予定です。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"対応について、今、お話しいただきました。他区と同様に、品川区も２２年の開設に向けて準備を進めているというふうに伺っています。大変な課題がある中、懸命に進められていると伺っております。そして、現実問題として、都区の協議がどうなるかは置いておいて、現実的に進めていかなければいけないですが、東京都とのこのようなすれ違いの中、どのように開設準備を進めていかれるのでしょうか。","respondent":"品川財政課長","answer":"これがどのような方向でつくかというところがわかりませんが、額は現在申し上げられないところはありますが、特別交付金というような形で申請をしているというような状況です。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、お話しいただいたように、今後の進め方については、当面は特別交付金でやらなければいけないというところなのですが、改めてまだ開設まで日にちがあって経費がかかっていく中で、先ほどの特別交付金のこともそうですが、区の見込みとしては、どのような形で、区の持ち出しで２２年まで相当抱えていかなければいけないのですが、そのあたりの通しについてはいかがでしょうか。","respondent":"品川財政課長","answer":"今年度、特別交付金で費用として申請しているのが、約１,０００万円というような形になってあります。それから、今年度、児童相談所の設計費等を予算計上しています。それ以後の見込みにつきましては、現在検討中ということで、金額は定かでございません。","id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"品川区でも、平成３０年、平成３１年で１億５１２万円という形で、実施設計でも数千万円かかっております。それと同時に財源の問題を解決しなければいけないのですが、最後に、改めて、都区の協議の中で区の主張を何とか通していこうというような決意といいますか、区側の強い主張を求めますが、それについていかがでしょうか。","respondent":"品川財政課長","answer":"来年度も財調交渉の中で、まず担当者間でも意見を出していきながら、部長会、それから区長会も通じて、東京都に意思を伝えていきたいと考えています。","id":"exchange-108"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、１１款分担金及び負担金の中で、民生費負担金、保育園保育料関係、それと、１４款都支出金、都補助金、これも保育関係です。それから１３款国庫支出金の学校施設整備費、それから時間があれば、１５款財産収入についてお聞きしたいと思います。学校は今、大分改築なさっている中で、改築の順番という変なのですけれども、それをどのように考えていくか、基準的なものを教えていただきたいと思います。","respondent":"佐藤保育課長、有馬庶務課長","answer":"区が進める幼児教育の無償化の考え方ですが、３歳から５歳児に関しては、原則、全員無償ということと、０から２歳児に関しましては、住民税非課税世帯が無償です。毎年１校ずつのペースで行っているわけですけれども、それを選定するに当たりましては、いわゆる築年数ですとか、学校の現状、いわゆる老朽度の関係、それから就学人口の動向、あるいは地域バランス。","id":"exchange-109"},{"speaker":"鈴木（真）委員","kind":"質問","question":"保育の関係です。この辺を区として、もし都の制度ができたときに、どういうふうに考えていくのか、その辺の考え方を教えてください。それから、学校関係です。前に学校の建築の年次一覧を調べてみたことがあるのですけれども、順番的に言うと、耐用年数的なものもお話があったと思うのですけれども、古い学校がまだ残っていると思うのですが、その辺はどう考えておられますか。","respondent":"佐藤保育課長、有馬庶務課長","answer":"予算額としては１３億円を見込んでおりますので、都内自治体の数で単純に割っても、各自治体２,０００万円ぐらいの歳入が見込めるというところです。それからもう１つは、比較すると、若干校舎は新しいかもしれないけれども、就学人口増に、今対応していかなければ受け入れが難しいだろうというところは。","id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"質問","question":"多子軽減についてです。補助金をもらったとしても、さっき言った５年間限定になったときに、多分５年の間でまた変わっていくこともあるかもしれないですけれども、その５年の負担を考えた場合、区としてどういうふうにやっていくのか、その辺を教えてください。古い学校をある程度、どのくらいの時期にというのは公表できないものなのですか。","respondent":"佐藤保育課長、有馬庶務課長","answer":"問題の５年間限定というところは、例えば、多子軽減を撤廃した場合に、成人で働いている方でも、長男であれば、それは多子と見るので、それは多子軽減なのかという議論もあると思いますので、いろいろ分析して考えたいと思います。なるべく早めの公表について検討していきたいと思います。","id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それぞれわかりました。学校のほうは、前はよく言われていた小学校が工事に入ったときに中学校は重ならないようにしたいという場面があったのか、うまくぶつからないようにやっていただきたいと、その辺、児童生徒がうまく使えるようにやっていただきたいと思います。もう１点確認したかったのが、財産収入、ここからちょうど見える劇団四季です。その辺、区は今どう考えているのか教えてください。","respondent":"立木経理課長","answer":"劇団四季の四季劇場の土地の貸し付けの件ですけれども、今年の７月１４日で１０年間の定期借地契約が終了いたします。劇団四季のほうから要望がございまして、平成３３年（２０２１年）１１月３０日まで延長するという公正証書を取り交わす予定です。","id":"exchange-112"},{"speaker":"塚本委員","kind":"確認","question":"そこで、まずこういった年ごとの実績とか、今後の後見人を必要とする人数の増加、この見方に関して、現状で特に間違いないかの確認と、それから、被後見人と、後見人候補となるような方のバランスというか、被後見人に対して後見人候補が十分にいらっしゃるというような状況にあるのか、はたまたその逆であるのかというような状況についてお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"委員ご指摘のように、例えば直近３年間で申し上げますと、平成２７年度が５０件の区長申立、平成２８年度は３６件、平成２９年度は５４件ということで、ご親族等々がいらっしゃらない高齢者の方にとりかわりまして、区長申立ということで家庭裁判所に申立を行い。","id":"exchange-113"},{"speaker":"塚本委員","kind":"質問","question":"この分かれる場合、どちらに行くのかというのはどういう話し合いというか、本人の後見人の見解とか、傾向とかあるのかわかりませんけれども、そこのところをお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"これが今のところの大きな流れになっているところです。","id":"exchange-114"},{"speaker":"塚本委員","kind":"質問","question":"そこで、どちらが後見人として決まっていくのかみたいなところです。ある種の最適化というか、そういったところについて、今までずっと延々と築き上げられてきた歴史というか実績があって、高い評価も得ているところだと思いますけれども、その点についての今後の展望を最後にお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"は受け皿をつくること、また、そうした中でケースに応じた形で品川成年後見センター、社会福祉協議会、あるいはその他の団体とのバランスを考えながら、後見制度の活用を今後とも図っていきたいというふうに考えているところです。","id":"exchange-115"},{"speaker":"塚本委員","kind":"質問","question":"先ほど、３月ですか、運動部の在り方に関する総合的なガイドライン、これは主に運動部ですけれども、運動部に限らず、例えば吹奏楽であれば、いろいろなコンクールとかもありますし、文化系のものも含めて、今、学校は申請があれば有償で外部指導員を招聘しているというか、そういう方を活用されているという中で、こういった父兄の声について、区としてどのような考えをお持ちになるかというところと。","respondent":"大関教育総合支援センター長","answer":"今回、教員の働き方改革も、これは日本全体で動いている流れに乗りまして、品川におきましても、試験的ですが、部活動指導員として教員にかわって大会の引率もできる新たな職を次年度位置づけたいというふうに考えておりますので、さまざまな形で地域の方、あるいは。","id":"exchange-116"},{"speaker":"塚本委員","kind":"質問・要望","question":"ご答弁にも絡むのですが、私が気にしているのは、部活動のさっきの総合的なガイドラインでも、教育的な視点を学校の部活動としては持つというところと、競技として実力を伸ばすというような専門的な、技術的なというか、そういう部分と両方がある種求められてくるのかと思います。働き方改革ということから出発している話かと思いますけれども、そこの点についてのお考えをお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"部活動指導員に関しましては、スポーツに関する専門性があるにこしたことはないのですが、それよりも、やはり学校教育の一部としてしっかりと服務のこと、あるいは生徒の発達段階に応じた科学的な指導、あるいは観戦、生活指導、生徒指導に関して教員、担任。","id":"exchange-117"},{"speaker":"塚本委員","kind":"質問","question":"もう少し話を進めたいところもあるのですけれども、時間がないので、またこれは改めてという形にしたいと思います。次に、１３９ページ、公共施設整備基金繰入金の中で、特に図書館の老朽化を少し耳にすることがあります。図書館によってということかもしれませんけれども、老朽化、築年数等はどのような現状になっているのか教えてください。","respondent":"横山品川図書館長","answer":"図書館の築年数についてのお尋ねです。品川図書館は昭和３８年改築で、平成７年に新装オープンしている状況ほか、地区館につきましては、昭和の４０年代のものがかなり多いような状況になっておりますので、築年数については４０年以上のものが大半を占めております。","id":"exchange-118"},{"speaker":"塚本委員","kind":"質問","question":"具体的に言えば、源氏前図書館などは２階にあって、そこに高齢者の方が上がっていくのは大変にご苦労があるということで、利用者からのいろいろな声が届いているかと思うのですけれども、こういった中で、今後、図書館の整備、あるいは老朽化に対する対応といいますか、こういったことにしっかりとした計画を持って対応していく時期かとも思っておりますけれども。","respondent":"横山品川図書館長","answer":"しかしながら、老朽化については早急に対応しなければいけないということは自覚しておりまして、そちらにつきましては、地区図書館のほとんどが複合施設ですので、それぞれの所管課と協議を始めなければいけないということで、具体的に昨年度から検討を始めている状況です。","id":"exchange-119"},{"speaker":"塚本委員","kind":"質問・要望","question":"今ご答弁いただいたところで、大変に前向きだと思いますけれども、しっかりと計画を練って、早急な対応ができれば、区民の皆さんの今のご要望におこたえいただくようお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８５ページ、１０５ページになりますけれども、障害者自立支援給付費についてお伺いしたいと思います。補装具については、自立支援給付で全国一律の制度ということになっていますけれども、視覚障害者のための補装具で盲人安全つえがあると思います。これはどういうふうに使い分けていくのか。それから、補装具としての盲人安全つえというのは、住民税非課税世帯でも自己負担となるのか。","respondent":"松山障害者福祉課長","answer":"それから白杖の再支給のことですけれども、告示でこちらの耐用年数は５年間として決められておりますが、どうしても著しい破損をした場合につきましては、再支給を行ってあります。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"社会福祉協議会の窓口の白杖も、かなりの方が使われていると思うのですけれども、白杖の交付は、そういう補装具がありながら、社会福祉協議会で白杖の交付をする理由というか、目的はどういうものなのかということと、それからあと、社会福祉協議会での白杖交付にかかる財源は、品川区のほうから出ているのか、それとも社会福祉協議会で出しているのか、窓口だけが社会福祉協議会ということになっているのか。","respondent":"松山障害者福祉課長","answer":"ただし、補装具の場合につきましては、きちんとその方のご事情に合わせてつくるということなので、社会福祉協議会の再交付がなければ、補装具のほうの支給で対応しております。","id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私、社会福祉協議会のほうがこういう地域生活支援事業ということであれば、ぜひ５年間は再交付が受けられないというこれを改善していただきたいと思うのです。これも多分、５,０００円程度だと思うのです。そういう方については、品川区の財源で出しているということであれば、５年間の制限をなくしていただきたいと思うのですけれども、それが１点です。２点、お願いします。","respondent":"松山障害者福祉課長","answer":"５年間再支給しないことの改善ですけれども、杖に関しては、今のところ、根拠としているのが国の告示です。社会福祉協議会による杖で対応できない場合は、きめ細かな形で、補装具のほうで対応はしていますので、今のところ社会福祉協議会での再支給は考えておりません。","id":"exchange-123"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、視覚障害者の方に責任を求めるのではなくて、ぜひ５年間の制限をなくしていただくということでご検討いただきたいということで、強く要望させていただきたいと思います。もう１つですけれども、次は重度訪問介護について伺いたいと思います。支給決定の見直しもされたことで、今後どう変わっていくのか。時間を増やしてほしいと求められたときには増やすことができるのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"それに基づいて、区としては、適切であるということで、支給決定を行っているです。次に、支給決定の見直し後の対応ということについてですけれども、今回、改正した要綱の基準につきましては、地域拠点相談支援センターに周知を行っております。","id":"exchange-124"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さまざま本当に最低レベルという状況になっているので、品川区だから受けられないというふうなことは、ぜひともなくしていただきたいですし、また、今年度から始まった福祉計画の中にも、ＰＤＣＡサイクルの中でこれをしっかりと盛り込んだ形で見直しを進めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"品川区の時間数についての対応です。こちらは地域拠点相談支援センターの相談員がきちんとご本人の希望を聞いて、希望に沿った生活ができるよう、障害者に寄り添った相談を今後とも丁寧に進めてまいります。","id":"exchange-125"},{"speaker":"本多委員","kind":"質問・要望","question":"１４７ページの特別区競馬組合配分金について、１５３ページの東京都競馬株式配当配分金について、もう少し詳しく教えていただきたいと思います。説明では、特別区競馬組合配分金については、対前年１０.９％の増という説明をいただきました。この両方につきまして、もう少し詳しく教えていただきたいと思います。","respondent":"米田総務課長、立木経理課長","answer":"一番大きなものですが、競馬の事業の利益に応じた各区への分配金という特別区分配金がございまして、こちらにつきましては、平成３１年度は。１５万９,８３２株持ってございまして、配分金は１株当たり１５円、その２回分ということでこちらの金額を計上しています。","id":"exchange-126"},{"speaker":"本多委員","kind":"質問","question":"数字の上で伸びているので、本当に歓迎するところです。大井競馬場について質問するのですが、もし運営について入ってしまったら、区としてお答えできる範囲でお願いしたいと思います。売得金額が対前年１０２％伸びている。メインレースの「スマイルシティ・しながわ」のほかに、例えば「品川区水辺千本桜賞」とか、こうした取組みについて、今後の区という立場からの考え方について教えてください。","respondent":"米田総務課長","answer":"昨年からスマイルシティ・しながわデーということでの１日品川の日というようなことで、特別区競馬組合と協議いたしまして実施をしています。","id":"exchange-127"},{"speaker":"本多委員","kind":"質問・要望","question":"区政参画に大いに役立てていただきたいと思います。関東最大規模のイルミネーション、これは大井競馬場を開催していない日に開催しているということですから、直接は関係ないかもしれませんが、その辺のメリットやつながりがあれば教えていただきたいのと、ただ、開催日はイルミネーションをほとんどつけていませんが、一部つけているものもあって、かなりイルミネーションを楽しめるなというふうに感じます。","respondent":"米田総務課長","answer":"こちらは５年前ぐらいは１割ぐらいの女性の入場比率だったものが、直近の調査によると、２割から、日によっては３割ということで、特に女性の方の集客が得られているということで、一定の効果を見込めたということで伺っております。","id":"exchange-128"},{"speaker":"松永委員","kind":"質問","question":"本日は、５０ページの特別区たばこ税の３０億５,８００万円について、７５ページの自転車駐輪場使用料について、時間がありましたら、６３ページの歴史館使用料について伺いたいと思います。初めに、５０ページの特別区たばこ税の３０億５,８００万円について伺います。そこで改めて伺いますが、このたばこ税の３０億５,８００万円の振り分けについてですが、大きくどのような分配になっているのか。","respondent":"伊東税務課長","answer":"たばこ税の３０億円余のその先のお話だと思いますけれども、たばこ税に関しましては歳入における一般財源です。というわけで、その後のことに関しては、その中からそれぞれの事業に使っているということになります。","id":"exchange-129"},{"speaker":"松永委員","kind":"質問","question":"喫煙者にかかわる費用も、その辺もわからないということでよろしいでしょうか。この条例には、喫煙ができる場所で喫煙をする際、受動喫煙を生じさせることがないよう、周囲の状況に配慮しなければならないと、都民の責務であると定められており、この責務に関する規定は、平成３１年１月１日の段階で施行され、既に始まっております。先ほど述べたような意見を区民から聞いているのかお伺いします。","respondent":"菅生活安全担当課長","answer":"その他６カ所につきましては、設置できる場所が、他の交通の妨害にならないとか、あるいは、いろいろな問題があってつけられないところを除きまして、つけられるところにはつけていくという考えです。","id":"exchange-130"},{"speaker":"松永委員","kind":"質問","question":"いずれ品川区でも、こうした場所が見受けられるようになってくるのではないかと考えます。そこで本区として、全国的に広がっている喫煙所について、どのような考えを持っておられるのか伺います。この設置場所がなければ、空き家または空き店舗を活用することもできるのではないかと思うのですが、この考えについて、本区のご意見を頂戴したいと思います。","respondent":"菅生活安全担当課長","answer":"指定喫煙所につきましでは、現在、９カ所と先ほどお話もしましたけれども、やはりまだ適地の問題がありましたので、なかなか増やすことが今難しい状況です。そういったＪＴの取組みを参考にしながら、区としてもいろいろ考えていきたいと考えております。","id":"exchange-131"},{"speaker":"松永委員","kind":"質問","question":"７５ページの自転車駐輪場使用料について伺います。そこで、駐輪場の場所について、主に駅近くに設置されていると思いますが、駅近くというと、駅は４０駅あるのですけれども、そのうち何カ所の駐輪場が設置されているのでしょうか。駅近くに駐輪場が設置されていない場所について、現状がもしわかれば教えてください。","respondent":"古郡交通安全担当課長","answer":"駐輪場の設置がないところは、大崎広小路駅と大森海岸駅になっております。自転車の利用状況については、全体ですけれども、９０％前後の利用率で推移をしているような状況です。","id":"exchange-132"},{"speaker":"松永委員","kind":"質問・要望","question":"そういう状況も含めて、今後、国道になりますので、国土交通省の管轄になると思うのですけれども、何か国に対してアクションとかを起こされているのでしょうか。今現在の状況をお知らせしたのですが、本区のホームページを確認したところ、自転車・バイク等の放置禁止区域に指定されておりませんでしたので、せめて指定していただくような要望とかをされているのかお伺いします。","respondent":"古郡交通安全担当課長","answer":"放置禁止区域につきましては、やはり駐輪場が設置されていないと放置禁止区域に指定ができないということもありますので、適地を探しながら駐輪場の設置等を今後の課題として放置禁止区域の設定をしていきたいと思います。","id":"exchange-133"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひそうした現状も踏まえて、今後進めていただけたらと思います。時間がないので、最後に要望で終わりますが、大森駅前住宅前駐輪場の件ですけれども、今現在、住民の方と定期的に駐輪場の状況、また今後どうされていくのかというお話し合いをされていると思います。ぜひ今後、定期的に改めて近隣住民の方々へ現状の説明、また意見交換を引き続き進めていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"伊藤委員","kind":"質問・要望","question":"庁舎使用料でありますけれども、保護司会のサポートセンターが設置されました。内容としては地域活動課になると思うのですけれども、再犯防止推進法が制定されて、品川区も具体的な計画策定を求められるようになりましたし、改めてサポートセンターを設置されたわけであるから、このことを契機に新たな対応をしていくと思うのですけれども、品川区としてどのように計画を進めていくのかお聞かせください。","respondent":"伊崎地域活動課長","answer":"更生保護サポートセンターにつきましては、３月上旬に、サポートセンター開設準備室を設置されたというところでございまして、来年度のサポートセンターの本格的な開設に向けて、今、保護司会の皆様で準備を進めているという段階だと聞いております。","id":"exchange-135"},{"speaker":"伊藤委員","kind":"質問・要望","question":"後段の部分にちょっと矛盾がありまして、今までなかったことを品川区に求められているわけであります。もちろん保護司の仕事も大きな仕事ではあるのだけれども、犯罪を犯した方の更生について、行政が一定の責任を持つということが法律で決められたわけであるから、それは東京都の計画も勘案しながら具体的に進めていっていただきますように、改めてお願いいたします。お願いいたします。","respondent":"立木経理課長","answer":"何かしら、例えば看板等を設置できるようであれば、庁舎側のほうで何かしら工夫は考えてまいりたいと考えております。","id":"exchange-136"},{"speaker":"伊藤委員","kind":"意見","question":"そのことはよくわかっているのです。だけど、この問題は皆さん共通にかかわるものだと思うのです。だから、そのようなことを具体的に展開していく中で、今、厳しい現状を克服して、品川区役所の出入口にしていくことが、結果として区民サービスの向上につながると思うのだけれども、改めて答弁をお願いしたいと思います。","respondent":"多並道路課長","answer":"今の委員のご指摘の箇所につきましては、補助１６３号線道路整備について、全体整備の線形もありますけれども、実際には、６５ｍの暫定整備という形で庁舎の前のところについてはつくる予定にあります。","id":"exchange-137"},{"speaker":"伊藤委員","kind":"質問","question":"物理的、それから法的なものではあるでしょうから、こういうことができないと思うからなかなか難しいのはわかるのだけれども、もっと長い目で見れば、品川区役所の建て替え計画も含めて、そのときには道路の接道部分であるとか、それから、区役所の入り口の部分について、十分検討していただいて、現下の道路交通の中であっても、多くの方々が安心して来ていただけるようなことを計画していく。","respondent":"多並道路課長","answer":"今、委員のご指摘のとおり、将来的な長いスパンの考え方、また、その前の直近の今の道路が終わった後の整備の形状の考え方、区民の皆様がご利用しやすいという観点で、よりよい形でできるように、法的な部分のいろいろなハードルは高いところがありますけれども。","id":"exchange-138"},{"speaker":"伊藤委員","kind":"質問","question":"地方消費税交付金については、５２ページを見る限りでは、前年度と比べて減額となっているのでありますけれども、予定では、本年１０月に消費税増税が予定されているわけであります。ですから、ぜひ品川区におきましては、消費税増税はされるけれども、こういう部分にも使われています、つまり、社会保障費であるとか、そういうことについてＰＲするべきだと思うのですが、いかがでしょうか。","respondent":"品川財政課長","answer":"金額ですが、前年度より金額が落ちているという部分につきましては、こちらはちょっと細かい話になりますけれども、国の徴収する月数がございまして、この月数がちょうど１１月で締めになるのですけれども、１１月末日が土曜日となりまして、これが１２月分に回るということで。","id":"exchange-139"},{"speaker":"南委員","kind":"質問","question":"集会所に関してですが、２カ所を除いて品川区内の区民集会所には和室が整備されています。今、高齢化で住民の方は和室を利用する際にも正座でなく椅子に座りたいという希望があると思うのですけれども、その辺の状況がどうなのかをひとつ伺いたいと思います。そして、その和室に椅子やテーブルが整備されている施設はどのくらいあるのか、それについても伺います。","respondent":"伊崎地域活動課長","answer":"区民集会所です。大井第一地域センターを除きまして、１２カ所の地域センターに区民集会所が併設しております。こちらにつきましては、和室に椅子が整備をされているところは、７カ所の地域センターに和室用椅子というものを整備しています。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"特に八潮の集会所には、和室２つと広間があります。特に八潮の２階の和室は、座卓そのものがすごく重たいのです。一刻も早くこれは改善していただきたいと思っているのですけれども、そのことについて、課長は認識をしていただいて、努力もしていただいているというふうに思うのですけれども、その大変さを解消することを優先していただきたいと思っているのですが、それについて伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"しかしながら、同じ機能を求めますと、どうしても同じぐらいの重さになってしまうということで、今でも探しています。何かいいものがございましたら、買い替えていくことは考えております。","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、私は２０１４年と２０１５年にシルバーセンターをつくってほしいという質問をいたしました。これはなぜかというと、命の問題だからなのです。そういう点で、１３カ所のシルバーセンターのうち８カ所に入浴設備があるのは、私はいいと思っているわけですけれども、他地区より高齢化が進んでいる八潮にはやっぱり必要だと思うのですけれども、この点についての見解、認識を伺います。","respondent":"宮尾高齢者地域支援課長","answer":"八潮地区に入浴設備つきのシルバーセンターをというお尋ねをいただいたと思います。八潮地区には、委員が今おっしゃられていたように、各住戸には基本的に入浴設備は整っているという認識をしております。","id":"exchange-142"},{"speaker":"南委員","kind":"質問","question":"前に質問したときと全く変わらない答弁です。私は、人の命がかかっているのだという実例を挙げて紹介してつくる必要があるのではないかと聞いたのです。そのことには触れていないですね。答弁してください。","respondent":"宮尾高齢者地域支援課長","answer":"おひとり暮らしの高齢者の方を見守るというのは、シルバーセンターとはまた違うところで、いろいろできるのかと考えているところです。","id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"見守るとおっしゃるけれども、どうやって見守るのですか。ひとりで入浴しているところをどうやって見守るのですか。私の質問趣旨を全然つかまない答弁、これでは納得できません。きちんとしていただきたいと思います。そういう状況を見たときに、特にそこを何とか救って命を守っていこうという、そういう視点には立たないのですかということをひとつ聞いたのですが、それについてはお答えがありません。","respondent":"寺嶋高齢者福祉課長、宮尾高齢者地域支援課長","answer":"ひとり暮らしのご高齢の方の入浴の困難さ等につきましては、地区の在宅介護支援センターのケアマネジャー等がご相談に応じて、可能な範囲でしかるべき対応をしています。そこにあいているからといって、すぐにどうこうというところは、また別な検討が必要かと思います。","id":"exchange-144"},{"speaker":"南委員","kind":"質問","question":"改修制度があるから、だから命を救えるのですかというふうに私は聞いているのです。ひとり入浴だと命が救えない。緊急通報装置をつけるのかもしれないけれども、そういうことではなくて、やっぱりさっき紹介した２人のケース、深刻ではないですか。そういうことをなくすという点で、ぜひ検討してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"若林委員","kind":"質問","question":"歳入全般というか、４７ページの総括の表を見ながらと、５８ページの使用料、これは電柱に関連して街路灯の関係について伺いたいと思います。全般的に総括の表を見まして、来年度の予算が１,８７７億円余と、過去最高となったということで、これは大変にすばらしいなというふうに思う一方、この質疑の中でも喜んでばかりはいられないというような一方の意見もごもっともなご質問、意見が出ています。","respondent":"品川財政課長","answer":"平成３０年度の決算から新たな公会計システムで財務４表も出していくというような形になるかと考えています。予算との絡みになるところですが、こういった平成３０年度の実績を重ねまして、決算のときに財務４表というような形で出すようになっております。","id":"exchange-146"},{"speaker":"若林委員","kind":"質問・要望","question":"事故が起こるということは、小さなことが幾重にも積み重なって大きな事故になっていくということの１つの戒めでもあると思いますので、これについて、仙台市のことですので、監査がそのときにどうなっていたのかということも頭をちらっとよぎりましたが、今日は監査のことは聞かないで、実態、原因について、品川区の今の現状、認識をお知らせいただきたいと思います。","respondent":"多並道路課長","answer":"街路灯の支払い、もしくは解約の件ですが、街路灯については、１灯１灯契約という形をとっております。","id":"exchange-147"},{"speaker":"若林委員","kind":"確認","question":"品川区の対応を街路灯についてお聞きいたしました。契約については、ほかにもいろいろガスとか何か契約もあると思います。毎年２回にわたる監査の状況も見させていただいて、品川区の監査はしっかりと行っているという状況も確認しておりますので、今後ともどうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"枝打ちだとか、下草刈りだとか、伐採、間伐、そういうものの体験、それから木育、こういうものは、木育なども今はどんどんやっていって、補助金も結構出るような制度もあるので、せっかくこういうことがあったので、これを機にいろいろな形で、いろいろなところに結びつけていってほしいと思うのだけれども、ぜひそういうふうに全体的に広げていくという感覚を。","respondent":"品川財政課長","answer":"やはり１つには、学校改築で、例えば、御殿山小学校などで木を使ったデザインだとか、そういったものをやっている事例がありますので、改築工事につきまして、今回も城南小学校でやっていくような形で進めているのが、１つやり方としてはあるかと思います。","id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１点、森林環境譲与税の使い道はわかっています。こういうことがこれからいろいろ出てくると、そういう部分で、ここでちょっと使おうかなというのではなくて、全体を見渡してもらって、いろいろな方法、これを機会にぜひその枝葉を広げてほしいわけです。だけど、そういうことも含めた、教育も含めた、どんどんそういう広がりをもう一度ぜひ考え方をどうしていくかということを教えてください。","respondent":"小林環境課長","answer":"間伐材の有効活用ですが、間伐材の伐採体験というところに関して言えば、今、商店街連合会と連携して、青梅に行くバスツアーを組んで体験をやっていただくようなことを進めているところですが、参加人数がなかなか限られてしまうところもありますので。","id":"exchange-150"},{"speaker":"須貝委員","kind":"確認","question":"私は、１０３ページ、いじめ防止対策事業補助金について確認したいと思います。文部科学省による全国の調査結果、平成２９年度もそうですが、だんだん増えているという状況なのですが、品川区の現状はどうなっているか教えてください。そして、区の取組みは年々変わっているのか、何か改善しているのかを教えてください。","respondent":"大関教育総合支援センター長","answer":"特に未然防止ということで、早めにＳＯＳを出せるように、ＨＥＡＲＴＳのスクールカウンセラー、スクールソーシャルワーカーおよび指導主事等が学校を訪問して、教室の様子を見たり、子どもたちが、例えば目安箱に書いてくれたことを１件１件丁寧に対応している。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問・要望","question":"自分のお子さんですから本来なら主に家庭で対応しなければいけないということだと思います。本当に大変だと思うのですけれども、今こういうふうな状況になったのですから、しっかりやっていただきたいと考えています。千葉県野田市において、先だって痛ましい事件がありました。品川区は、同じ自治体として本当に大丈夫なのでしょうか。それを教えてください。お願いいたします。","respondent":"大関教育総合支援センター長","answer":"ですから、関係機関との月ごとに行われるような連絡会、あるいは学期ごとに行われる連絡会において、個別のケースの情報共有も含めまして、丁寧にやっているところです。これはあってはならないことだということを肝に銘じながらも、未然防止に精いっぱい努めている最中です。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"向き合える時間があるのか。例えば、保護者ならば、毎日朝、普通なら「おはようあります」とあいさつをする。顔色を見て、態度を見て、何か下を向いているな、何か食欲がないなというのは、やはり先生にも頼らざるを得ないのですが、こういう向き合う時間はあるのでしょうか。私は、連携よりそばにいる、現場にいる先生の観察力というか、その対応が大事だと思うのですが、その辺についてどうでしょうか。","respondent":"大関教育総合支援センター長","answer":"朝、登校してくるところで挨拶当番の児童生徒と一緒に教員が立ち番をしながら様子を見て、おかしいなと思い、一言声をかけたときに、返事がどうも暗いな、そういった部分を気づくのが、やはり教員だと考えていますので、そこで何かあった際には、もしかすると。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"今、品川区は若い先生が多くて、おそらく子どもを育てたことがない先生もまだたくさんいらっしゃると思うのですが、そういう方で本当に大丈夫なのでしょうかという不安が保護者の方にあると思うのですが、それもあとでお聞きします。セクハラがあるのです。そうしたら、子どもたちはそこで今度、生きていけないのではないですか。このようなやり方で放置していていいのでしょうか。教えてください。","respondent":"大関教育総合支援センター長","answer":"起きたときにしっかりと当事者同士でどうしていくかを考える場面もあったり、あるいは本人とご家庭が、どのように乗り越えていくかというのは、１つの成長のいいチャンスだという見方もあるというふうに昔から言われています。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、やっぱり社会に船出したときに、そこで乗り越えていける力を養うかということも、今後しっかり考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-155"},{"speaker":"石田（し）委員","kind":"質問","question":"その前段の質問にもかぶってくるのですけれども、使用料をもしそのまま据え置きにするのであれば、どこかにその増税分の影響が来るわけであって、それが前の５％から８％に増税されたときには、使用料はそのままに据え置きにされて、どこに負担が来たかというと、指定管理者がやっている運営費の中で負担がかかってしまったという話を聞いたことがあるので、それを含めて。","respondent":"品川財政課長、柏原企画調整課長、佐藤保育課長、鷹箸保健予防課長、大関教育総合支援センター長","answer":"歳入分につきましては、大きく地方消費税交付金に影響があるのですが、大体締めの月は１１月になりますので。これは前回上がったときと同様でございまして、現段階では使用料の改定は予定をしていないです。次に、指定管理の部分です。保育園も０から２歳児は変更なしなのですが、３から５歳児に関しましては。ボランティアの従事者の方への対応ですが、ボランティアについては、東京都で募集しているボランティアと。性感染症を扱う性教育の部分ですが、９年生の保健体育で、エイズおよび性感染症の予防として。","id":"exchange-156"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"この徴収事務は誰が担うのか、その点も教えてください。感染症の部分ですが、前回の代表質問のときも、何かがあったときのためにしっかり対応しますという答弁だったのですが、私は違って、前段階で予防ができる感染症に関しては、しっかり予防の段階でするべきではないですかという質問をしているので、ぜひそこは、これは要望でとどめますけれども、ぜひ検討を進めていってください。","respondent":"佐藤保育課長","answer":"実際に品川区の保育園児が給食費をどうするかということなのですが、先日、東京都で２３区全部を調査したところ、２２区について取り扱い未定という状況で、今後、主管課長会等で詳しく議論していくことになると思います。","id":"exchange-157"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"中で吸えなかったらどうするのか。吸う人は外で吸うようになってしまうので、やっぱり喫煙所の整備はしっかり区としても対応していただきたいと思います。これは喫煙者の方にとってもそうですし、受動喫煙を望まない方のためにもそういった対策は町なかでもしっかりとるべきだと思うので、これは過料は必ず増えてくると思うので、しっかりその整備をしていただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、１２５ページの土木費補助金の中のやさしいまちづくり整備費から、鉄道駅のバリアフリー化について伺いたいと思います。平成３１年度は、可動式ホーム柵が東急大井町線の下神明駅と戸越公園駅に設置をされる予定です。","respondent":"鈴木都市計画課長","answer":"自治体の上限、区の上限は３,０００万円ですが、今回、下神明駅と戸越公園駅は、１日の平均利用者数が１０万人以下というところでございまして、都の補助金がスキーム上入ってこないというところと、それから、国のほうは。","id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問","question":"助成金の規定といいますか、そこの中に入ってこなければ助成金は出ないということなので、やっぱり鉄道事業者が頑張ってつけるという状況にもなってくるかなと思うのですが、鉄道駅のバリアフリー化が、オリンピック・パラリンピックに向けて次々進んでいくと思うのですけれども、昨年の決算のときに、私、下神明駅から線路に転落して亡くなってしまったという事件を踏まえて。","respondent":"鈴木都市計画課長","answer":"昨年の９月の下神明駅での痛ましい死亡事故を受けまして、区のほうで、昨年の１１月２０日付ですが、区長名で各鉄道事業者のほうに、強い申し入れの文書を出させていただいたところです。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それについて、各事業者の返答はどういうものだったのか、わかれば伺いたいのですけれども、この間ずっと私も取り上げてきています京急新馬場駅南口のバリアフリー化ですけれども、近隣住民の皆さんも５年間にわたって求め続けているところですけれども、京急に対して、新馬場駅南口にエレベーター設置については、区も要望していただいているということですけれども。","respondent":"鈴木都市計画課長","answer":"ただし書きで８分の１まで緩和されるという記載もありますが、そうした数字の解釈は当然根拠を持って鉄道事業者と改善に向けた話し合いを、今、行っているところです。","id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、エレベーターは、設計やお金等々もかかってくる、時間が一定かかるかと、早くつけてほしいですけれども、一定時間がかかるものだと思うのですけれども、点字ブロックを歩道までつなぐ、勾配をやわらげるというのは、比較的すぐに取組めるものだと思うのですけれども、５年経っても進んでいない状況に対して、区はさらに、今、協議を続けているということですけれども。","respondent":"鈴木都市計画課長","answer":"平成２８年に地域の方が京急電鉄のほうに要望書を出されて、それに対する回答も区では入手して状況を把握しています。１つは、私は昨年の６月に鉄道事業者、その後、７月に地域の方とお会いしていろいろ話もしています。","id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どうしてあれがユニバーサルデザインなのかよくわからないという、そういった声もありますので、やっぱり利用者の声に重きを置いて整備をしていかないと、結局、よかれと思ってつくったものが、障害者や高齢者にとっては使いづらかったという状況になるというのは、この間も区の中でもあると思うので、こうした駅においても、区としては、住民の立場のほうに立っていただきたいと思いますし、そういう立場で。","respondent":"鈴木都市計画課長","answer":"引き続き、鉄道事業者、地域の声をお聞きしながら、全て一気にということではなくて、改善できるところについて協議を重ねながら申し入れをしていきたいです。","id":"exchange-163"},{"speaker":"こんの委員","kind":"質問","question":"避難道路機能強化事業、関連して、津波、高潮の避難経路、道路、これについてお伺いしたいと思います。そのためには、避難経路、道路の整備、対策が必要と考えております。このような課題があるところが、いざ災害時に避難経路となることについて、区はどのようにお考えでしょうか。区の認識と見解をお伺いしたいと思います。避難経路として何か対策をお考えでしたら、その点もお聞かせください。","respondent":"高梨木密整備推進課長、持田河川下水道課長","answer":"最初に私から、避難道路機能強化事業について説明をします。そこから目標とする高台等に向かってどういうルートをとればいいかという形で、例えば、事前にそういったところを下見といいましょうか、見ていただきながらルートを示していただきたいというような形をしてございまして。","id":"exchange-164"},{"speaker":"こんの委員","kind":"質問・要望","question":"今のご説明で、確かに経路を事前に確認をしましょうというワークショップは存じております。これに対して区はどう思っているかということをお聞きしたわけです。事前に皆さんが通る経路は、当然、どこが通れるのかは考えていただきたいのは、そうしたことは必要でしょうけれども、ハード面ではどのように対策をとらなければいけないのか。ここをお聞きしたわけですが、どのようにお考えでしょうか。","respondent":"多並道路課長","answer":"ただ、逃げる際の課題は、想定していなかったためいつもの利用の面と、災害時の面と、両方とも兼ねるような行動ができないかというのは、引き続き、どういうことがあるかというのは研究していきたいと思っているところです。","id":"exchange-165"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ研究をしていただきたいと思います。ですので、ここはそうしたことも考えながら、今の時点でベビーカーや車椅子が通れない課題も出てきているので、こうしたところを早急に研究して、そこを避難路としても、平常時に使えることとしても研究を進めていただきたいと思いますが、もう一度、そのお考えをお聞きします。","respondent":"多並道路課長","answer":"長期的な視点で言えば、都市計画道路の整備かと思いますけれども、短期的な面で申しあげれば、今の委員にご指摘いただいたような部分があるかと思いますので、どういう形ができるかというのは、逃げる方の心理面であったり、どう逃げればいいかという課題を洗いながら。","id":"exchange-166"},{"speaker":"こんの委員","kind":"質問・要望","question":"この道路は非常に大事な道路でありますし、確かに都市計画道路にかかっているところかもしれませんが、この隧道に関してだけ言えば、避難路としては早急に考えていただきたいところでもありますので、よろしくお願いいたします。次にいきます。次は、居住支援事業ですけれども、ここは確認です。どのように捉えてこの協議会を進めようとお考えでしょうか。","respondent":"森住宅課長","answer":"居住支援協議会についてです。来年度、具体的に協議会の設置に向けて進めてまいりたいと考えております。住宅確保要配慮者につきましては、国のほうで、あるいは東京都でもさまざまな事例が挙げられております。","id":"exchange-167"},{"speaker":"こんの委員","kind":"質問・要望","question":"いわゆる低家賃での居住、住むところの戸数がそもそも少ないというところのハード面の手当ても必要ですし、また、連帯保証人とか、あるいは緊急連絡先、いわゆる見守りというソフト面のそうした手当ても必要ですし、両面から考えていかなければいけないというときに、例えばハード面については、空いているお部屋、空いている家、こうしたものの利活用ということもあわせて考えていただきたいと思いますが。","respondent":"森住宅課長","answer":"受入先として、空き家、空き室も含めて、この協議会の中で検討してまいりたいと思います。","id":"exchange-168"},{"speaker":"渡部委員","kind":"質問・要望","question":"７５ページ、学校施設使用料のところと、１４５ページ、りんかい線の関係で聞きます。というのは、もう実は話が結構できていて、りんかい線はＪＲに譲渡するのですか。それとも、その辺の羽田アクセス線等に関して、当然、品川区も株主、１.何％ですけれども株主ですから、これは何らかの話がもう届いているのではないかと思うのですけれども、その辺、もし教えていただけることがあれば教えてください。","respondent":"鈴木都市計画課長、有馬庶務課長","answer":"羽田アクセス線のお話ですが、今年に入ってからＪＲが３ルート、羽田空港から渋谷、新宿に向かうライン、それから東京駅に向かうライン、さらには臨海部に向かうライン、そのうちの東京駅に向かうラインについては。理由が部活であるということは何らかの理由があるかもわかりませんし、小学校であれば、もう少し前もってわかっているということもあろうかと思いますので、その辺は状況を確認して対応していきたいと考えています。","id":"exchange-169"},{"speaker":"渡部委員","kind":"質問・要望","question":"りんかい線のほうは、やはり東京都、ないし品川区で持っていてほしいなという思いはあります。言いたいことはいっぱいあるのですけれども、時間がないので要望で終わらせていただきます。ですから、例えば、調整会議にちゃんと出ているチームとかですと、例えば、４月のグラウンドを使うのは３月５日前後の調整会議なのです。だから、そういう仕組みをぜひつくってほしいと思うのです。お願いします。","respondent":"有馬庶務課長","answer":"今、委員ご提案の仕組みですので、学校側の理由であいた場合については、何らかの形で情報提供をしていくような形で検討していきたいと思います。","id":"exchange-170"},{"speaker":"渡部委員","kind":"質問・要望","question":"１点、お伺いいたします。これはすごくいいことで、そこそこ出ていると思うのですけれども、これまでの出ている枚数を教えていただきたいのと、これはたしか限定だったはずなのですけれども、限定数にそろそろ達するのかというふうに思うのですが、平成３１年度は限定を超えそうになった場合、新たにつくっていただけるのか、どうするのか、その辺をお聞かせください。","respondent":"伊東税務課長","answer":"来年度も、このままの推移であれば大丈夫だと思っているところです。その後に関しましては、今のところ、まだ検討していないという状況で、増やすのか、または別の形を考えるのかということも含めまして、まだ未着手の状態です。","id":"exchange-171"},{"speaker":"渡部委員","kind":"質問・要望","question":"多分、今、総数でお知らせいただいたのですけれども、白いものがたしか５０ｃｃの普通の原付のものだと思うのですけれども、あれが一番出ていると思うのです。あれは確実に配り切ってしまうのかと思いますので、要望としては、ぜひまた増産をかけていただいて、新しい番号を出すのであれば、お願いしたいということは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/430016?Template=document&Id=1092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":123614,"voices":398}},{"id":"r01-20190305-10","meetingId":"r01-cm03","date":"2019年3月5日","dateIso":"2019-03-05","committee":"議会運営委員会","time":"午後 ６時１０分～午後 ６時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/268822?Template=document&Id=5316#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":1307,"voices":12}}]);
